"use client";

import * as React from "react";
import { Mail, MailX, Trash2 } from "lucide-react";
import { ConfirmAction } from "./confirm-action";
import { NumberRoll } from "./number-roll";
import { RelativeTime, toTime, type DateLike } from "./relative-time";
import { StatusButton, type ActionStatus } from "./status-button";
import { TagInput, type TagInputProps, type TagInputTag } from "./tag-input";
import { RoleMenu, type TeamRole } from "./team-role-menu";
import { TextMorph } from "./text-morph";
import { useRowMotion } from "./use-row-motion";

/* ─────────────────────────────────────────────────────────
 * TEAM MEMBERS: Settings → Members, done properly
 *
 *   invite    addresses go into the invite field (paste a list,
 *             duplicates fly into their twins); "Invite 3" sends
 *             them, and each chip lifts out of the field and
 *             flies down onto its new row in the list
 *   seats     "4 of 5 seats" rolls as people come and go; the
 *             field takes no more than the seats that are left
 *   role      the role pill grows into the list of roles and
 *             folds back with the new one; a spinner rides in
 *             the pill while it saves, and a refusal morphs the
 *             old role back with a shake
 *   resend    pending invites count down "Resend in 0:28",
 *             then offer Resend, which says Sending and Sent
 *             and starts the clock again
 *   remove    the bin stretches into "Remove", a check draws,
 *             the row folds away and the rest glide up
 *
 * Members are plain records; every change is one async
 * function, so it works with Clerk, Better Auth, WorkOS or
 * your own table.
 * ───────────────────────────────────────────────────────── */

export type { TeamRole, DateLike };

export interface TeamMember {
  id: string;
  email: string;
  name?: string;
  image?: string;
  role: string;
  /** "invited" until they accept. */
  status?: "active" | "invited";
  /** When the invite was last sent; the resend clock runs from it. */
  invitedAt?: DateLike;
  lastActiveAt?: DateLike | null;
  /** The person looking at the page. */
  you?: boolean;
  /** Can't be changed or removed here, e.g. the owner. */
  locked?: boolean;
}

export interface TeamMembersProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "defaultValue" | "onChange"
> {
  value?: TeamMember[];
  defaultValue?: TeamMember[];
  onValueChange?: (members: TeamMember[]) => void;
  roles: TeamRole[];
  /** The role new invites start with; the second role by default. */
  inviteRole?: string;
  /** Seats on the plan. Members and pending invites both take one. */
  seats?: number;
  /** Sends invites. Return the new members (status "invited"); throw to keep the addresses and say why. */
  onInvite?: (emails: string[], role: string) => Promise<TeamMember[]>;
  /** Saves a role. Throw to put the old one back. */
  onRoleChange?: (
    member: TeamMember,
    role: string,
  ) => Promise<unknown> | unknown;
  /** Removes a member or cancels an invite. */
  onRemove?: (member: TeamMember) => Promise<unknown> | unknown;
  /** Sends an invite again. */
  onResend?: (member: TeamMember) => Promise<unknown> | unknown;
  /** Seconds before an invite can be sent again. */
  resendAfter?: number;
  /** People to suggest in the invite field (your directory). */
  suggestions?: TagInputProps["suggestions"];
  title?: string;
  description?: string;
}

type Actions = {
  role: (m: TeamMember, role: string) => void;
  remove: (m: TeamMember) => Promise<void>;
  resend: (m: TeamMember) => Promise<void>;
};

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const NONE: TeamMember[] = [];
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const SPLIT = /[\s,;]+/;
const lower = (v: string) => v.toLowerCase();
const validate = (v: string) =>
  EMAIL.test(v) ? null : `“${v}” isn’t an email address`;
const message = (e: unknown, fallback: string) =>
  e instanceof Error && e.message ? e.message : fallback;
const two = { minimumIntegerDigits: 2 };

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const initials = (m: TeamMember) =>
  (m.name ?? m.email)
    .split(/[\s@._-]+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((w) => w[0]!.toUpperCase())
    .join("");

function Avatar({ m }: { m: TeamMember }) {
  if (m.status === "invited")
    return (
      <span
        data-avatar=""
        className="grid size-8 shrink-0 place-items-center rounded-full border border-dashed border-border text-muted-foreground"
      >
        <Mail className="size-3.5" strokeWidth={1.75} aria-hidden="true" />
      </span>
    );
  if (m.image)
    return (
      <img
        data-avatar=""
        src={m.image}
        alt=""
        className="size-8 shrink-0 rounded-full object-cover shadow-[0_0_0_1px_var(--border)]"
      />
    );
  return (
    <span
      data-avatar=""
      aria-hidden="true"
      className="grid size-8 shrink-0 place-items-center rounded-full bg-muted text-[11px] font-medium text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]"
    >
      {initials(m)}
    </span>
  );
}

/** A piece of a line that opens and closes sideways (a countdown after "Resend in"). */
function Reveal({
  open,
  reduced,
  children,
}: {
  open: boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  return (
    <span
      aria-hidden={!open || undefined}
      className="inline-grid"
      style={{
        gridTemplateColumns: open ? "1fr" : "0fr",
        opacity: open ? 1 : 0,
        filter: open || reduced ? "none" : "blur(3px)",
        transition: reduced
          ? "none"
          : `grid-template-columns 380ms ${EASE}, opacity 260ms ${EASE}, filter 260ms ${EASE}`,
      }}
    >
      <span className="min-w-0 [clip-path:inset(-4px_0)]">{children}</span>
    </span>
  );
}

/** "Resend in 0:28", rolling down; then Resend → Sending → Sent, and the clock starts again. */
function Resend({
  since,
  after,
  reduced,
  onResend,
}: {
  since: number;
  after: number;
  reduced: boolean;
  onResend: () => Promise<void>;
}) {
  const [now, setNow] = React.useState<number | null>(null);
  const [status, setStatus] = React.useState<ActionStatus>("idle");
  const left = now === null ? 0 : Math.max(0, since + after * 1000 - now);
  const counting = now !== null && left > 0;
  React.useEffect(() => {
    const timer = window.setTimeout(() => setNow(Date.now()), 0);
    return () => window.clearTimeout(timer);
  }, [since]);
  React.useEffect(() => {
    if (!counting) return;
    const timer = window.setTimeout(
      () => setNow(Date.now()),
      1000 - (Date.now() % 1000) + 10,
    );
    return () => window.clearTimeout(timer);
  }, [counting, now]);
  React.useEffect(() => {
    if (status !== "success" && status !== "error") return;
    const timer = window.setTimeout(
      () => setStatus("idle"),
      status === "success" ? 1400 : 2400,
    );
    return () => window.clearTimeout(timer);
  }, [status]);

  const busy = status === "pending" || status === "success";
  const label =
    status === "pending"
      ? "Sending"
      : status === "success"
        ? "Sent"
        : status === "error"
          ? "Try again"
          : counting
            ? "Resend in"
            : "Resend";
  const s = Math.ceil(left / 1000);
  const ready = !counting && !busy;

  return (
    <button
      type="button"
      aria-disabled={!ready || undefined}
      aria-label={
        counting ? "Resend invite, available shortly" : "Resend invite"
      }
      onClick={async () => {
        if (!ready) return;
        setStatus("pending");
        try {
          await onResend();
          setStatus("success");
        } catch {
          setStatus("error");
        }
      }}
      className={`inline-flex cursor-pointer items-baseline rounded-sm whitespace-nowrap tabular-nums transition-colors duration-200 aria-disabled:cursor-default ${FOCUS} ${
        status === "error"
          ? "text-red-600 dark:text-red-400"
          : ready
            ? "font-medium text-foreground underline-offset-2 hover:underline"
            : ""
      }`}
    >
      <TextMorph>{label}</TextMorph>
      <Reveal open={counting && status === "idle"} reduced={reduced}>
        <span className="inline-flex items-baseline pl-[0.25em]">
          <NumberRoll value={Math.floor(s / 60)} direction="down" />:
          <NumberRoll value={s % 60} format={two} direction="down" />
        </span>
      </Reveal>
    </button>
  );
}

/** A refusal, lifted in over the line under the name and lifted out again. */
function Note({ text, reduced }: { text?: string; reduced: boolean }) {
  const [shown, setShown] = React.useState(text);
  if (text && text !== shown) setShown(text);
  return (
    <span
      aria-hidden="true"
      className="pointer-events-none absolute inset-x-0 top-0 truncate text-red-600 dark:text-red-400"
      style={{
        opacity: text ? 1 : 0,
        transform: text || reduced ? "none" : "translateY(-4px)",
        filter: text || reduced ? "none" : "blur(3px)",
        transition: reduced
          ? "none"
          : `opacity 260ms ${EASE} ${text ? 80 : 0}ms, transform 360ms ${EASE}, filter 260ms ${EASE}`,
      }}
    >
      {shown}
    </span>
  );
}

interface RowProps {
  m: TeamMember;
  roles: TeamRole[];
  saving: boolean;
  shake: number;
  /** Why the last change was refused; shown in place of the line under the name for a while. */
  note?: string;
  gone: boolean;
  canEdit: boolean;
  canRemove: boolean;
  canResend: boolean;
  resendAfter: number;
  reduced: boolean;
  act: React.RefObject<Actions>;
}

const MemberRow = React.memo(function MemberRow({
  m,
  roles,
  saving,
  shake,
  note,
  gone,
  canEdit,
  canRemove,
  canResend,
  resendAfter,
  reduced,
  act,
}: RowProps) {
  const invited = m.status === "invited";
  const display = m.name ?? m.email;
  const role = roles.find((r) => r.value === m.role)?.label ?? m.role;
  const removable = canRemove && !m.locked && !m.you;
  return (
    <li data-row-id={m.id} className="border-t border-border first:border-t-0">
      <div
        className="flex items-center gap-3 px-4 py-2.5 transition-opacity duration-300 @md:px-5"
        style={{ opacity: gone ? 0.5 : 1 }}
      >
        <Avatar m={m} />
        <div className="min-w-0 flex-1">
          <p className="flex min-w-0 items-center gap-1.5 text-[13.5px] font-medium tracking-[-0.01em]">
            <span data-name="" className="truncate">
              {display}
            </span>
            {m.you && (
              <span className="shrink-0 rounded-full px-1.5 text-[11px] font-normal text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]">
                You
              </span>
            )}
          </p>
          <p className="relative mt-0.5 text-[11.5px] text-muted-foreground">
            <Note text={note} reduced={reduced} />
            <span
              className="flex min-w-0 items-baseline gap-x-1.5"
              style={{
                opacity: note ? 0 : 1,
                filter: note && !reduced ? "blur(3px)" : "none",
                transition: reduced
                  ? "none"
                  : `opacity 220ms ${EASE}, filter 220ms ${EASE}`,
              }}
            >
              {/* On a narrow card the name is enough; the address comes back when there's room. */}
              {m.name && (
                <span className="hidden min-w-0 truncate @md:inline">
                  {m.email}
                </span>
              )}
              {m.name && (invited || m.lastActiveAt) && (
                <span aria-hidden="true" className="hidden @md:inline">
                  ·
                </span>
              )}
              {invited ? (
                <>
                  <span className="shrink-0 @md:hidden">Invited</span>
                  <span className="hidden shrink-0 @md:inline">
                    {m.invitedAt ? (
                      <RelativeTime date={m.invitedAt} prefix="Invited" />
                    ) : (
                      "Invited"
                    )}
                  </span>
                  {canResend && (
                    <>
                      <span aria-hidden="true">·</span>
                      <Resend
                        since={m.invitedAt ? toTime(m.invitedAt) : 0}
                        after={resendAfter}
                        reduced={reduced}
                        onResend={() => act.current.resend(m)}
                      />
                    </>
                  )}
                </>
              ) : m.lastActiveAt ? (
                <RelativeTime
                  className="shrink-0"
                  date={m.lastActiveAt}
                  prefix="Active"
                />
              ) : null}
            </span>
          </p>
        </div>
        {canEdit && !m.locked ? (
          <RoleMenu
            roles={roles}
            value={m.role}
            onValueChange={(r) => act.current.role(m, r)}
            saving={saving}
            shake={shake}
            label={`Role for ${display}`}
          />
        ) : (
          <span className="shrink-0 px-2.5 text-[12px] text-muted-foreground">
            {role}
          </span>
        )}
        {canRemove && (
          <div className="-mr-1 flex min-w-7 shrink-0 justify-end">
            {removable && (
              <ConfirmAction
                icon={
                  invited ? (
                    <MailX strokeWidth={1.75} />
                  ) : (
                    <Trash2 strokeWidth={1.75} />
                  )
                }
                label={
                  invited ? `Cancel invite for ${display}` : `Remove ${display}`
                }
                labels={
                  invited
                    ? {
                        idle: "Cancel invite",
                        pending: "Cancelling",
                        success: "Cancelled",
                        error: "Try again",
                      }
                    : {
                        idle: "Remove",
                        pending: "Removing",
                        success: "Removed",
                        error: "Try again",
                      }
                }
                onConfirm={() => act.current.remove(m)}
              />
            )}
          </div>
        )}
      </div>
    </li>
  );
});

export function TeamMembers({
  value,
  defaultValue = NONE,
  onValueChange,
  roles,
  inviteRole,
  seats,
  onInvite,
  onRoleChange,
  onRemove,
  onResend,
  resendAfter = 30,
  suggestions,
  title = "Members",
  description = "People in this workspace and the invites waiting on them.",
  className = "",
  ...props
}: TeamMembersProps) {
  const reduced = useReducedMotion();
  const [inner, setInner] = React.useState(defaultValue);
  const members = value ?? inner;
  const [tags, setTags] = React.useState<TagInputTag[]>([]);
  const [role, setRole] = React.useState(
    () => inviteRole ?? roles[Math.min(1, roles.length - 1)]?.value ?? "",
  );
  const [sending, setSending] = React.useState<ActionStatus>("idle");
  const [inviteError, setInviteError] = React.useState<string | null>(null);
  const [saving, setSaving] = React.useState<Record<string, boolean>>({});
  const [shakes, setShakes] = React.useState<Record<string, number>>({});
  const [notes, setNotes] = React.useState<Record<string, string>>({});
  const [gone, setGone] = React.useState<string[]>([]);
  const [announce, setAnnounce] = React.useState("");
  const rootRef = React.useRef<HTMLDivElement>(null);
  const fieldRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLUListElement>(null);
  const ghostRef = React.useRef<HTMLDivElement>(null);
  const flyRef = React.useRef<HTMLDivElement>(null);
  const flights = React.useRef(
    new Map<string, { rect: DOMRect; label: string }>(),
  );
  const latest = React.useRef(members);
  React.useLayoutEffect(() => {
    latest.current = members;
  });

  const commit = (next: TeamMember[]) => {
    if (value === undefined) setInner(next);
    onValueChange?.(next);
  };

  const used = members.length;
  const left = seats === undefined ? undefined : Math.max(0, seats - used);
  const valid = tags.filter((t) => !t.error);
  const ranks = React.useMemo(
    () => new Map(members.map((m, i) => [m.id, i])),
    [members],
  );
  useRowMotion(listRef, { reduced, ranks, ghosts: ghostRef });

  const act = React.useRef<Actions>(null!);
  React.useLayoutEffect(() => {
    act.current = {
      role: async (m, next) => {
        const prev = m.role;
        const name = m.name ?? m.email;
        const label = roles.find((r) => r.value === next)?.label ?? next;
        commit(
          latest.current.map((x) => (x.id === m.id ? { ...x, role: next } : x)),
        );
        setSaving((s) => ({ ...s, [m.id]: true }));
        try {
          await onRoleChange?.(m, next);
          setAnnounce(`${name} is now ${label}.`);
        } catch (e) {
          commit(
            latest.current.map((x) =>
              x.id === m.id ? { ...x, role: prev } : x,
            ),
          );
          setShakes((s) => ({ ...s, [m.id]: (s[m.id] ?? 0) + 1 }));
          const why = message(e, `${name}'s role couldn't be changed.`);
          setNotes((n) => ({ ...n, [m.id]: why }));
          setAnnounce(why);
          window.setTimeout(
            () =>
              setNotes((n) =>
                n[m.id] === why
                  ? Object.fromEntries(
                      Object.entries(n).filter(([k]) => k !== m.id),
                    )
                  : n,
              ),
            3600,
          );
        } finally {
          setSaving((s) =>
            Object.fromEntries(Object.entries(s).filter(([k]) => k !== m.id)),
          );
        }
      },
      remove: async (m) => {
        await onRemove?.(m);
        setGone((g) => [...g, m.id]);
        setAnnounce(
          m.status === "invited"
            ? `Invite for ${m.email} cancelled.`
            : `${m.name ?? m.email} removed.`,
        );
        // Long enough for the check to draw; then the row folds away.
        window.setTimeout(() => {
          commit(latest.current.filter((x) => x.id !== m.id));
          setGone((g) => g.filter((id) => id !== m.id));
        }, 700);
      },
      resend: async (m) => {
        await onResend?.(m);
        commit(
          latest.current.map((x) =>
            x.id === m.id ? { ...x, invitedAt: new Date() } : x,
          ),
        );
        setAnnounce(`Invite sent to ${m.email} again.`);
      },
    };
  });

  const invite = async () => {
    if (!onInvite || !valid.length || sending === "pending") return;
    setSending("pending");
    setInviteError(null);
    try {
      const added = await onInvite(
        valid.map((t) => t.value),
        role,
      );
      // Where each chip sits now, so its row can fly out of it.
      const at = new Map<string, { rect: DOMRect; label: string }>();
      for (const t of valid) {
        const el = fieldRef.current?.querySelector<HTMLElement>(
          `[data-token="${CSS.escape(t.id)}"]`,
        );
        if (el)
          at.set(t.value.toLowerCase(), {
            rect: el.getBoundingClientRect(),
            label: t.label ?? t.value,
          });
      }
      flights.current = at;
      commit([...added, ...latest.current]);
      setTags((ts) => ts.filter((t) => t.error));
      setSending("success");
      setAnnounce(
        `${added.length} ${added.length === 1 ? "invite" : "invites"} sent.`,
      );
    } catch (e) {
      setSending("error");
      setInviteError(message(e, "The invites couldn't be sent. Try again."));
    }
  };

  // New rows that came from chips: each chip's copy flies from the field onto its row's name.
  React.useLayoutEffect(() => {
    const queued = flights.current;
    if (!queued.size) return;
    flights.current = new Map();
    const root = rootRef.current;
    const layer = flyRef.current;
    const list = listRef.current;
    if (!root || !layer || !list || reduced) return;
    const box = root.getBoundingClientRect();
    let i = 0;
    for (const m of members) {
      const from = queued.get(m.email.toLowerCase());
      if (!from) continue;
      const row = list.querySelector<HTMLElement>(
        `[data-row-id="${CSS.escape(m.id)}"]`,
      );
      const name = row?.querySelector<HTMLElement>("[data-name]");
      const avatar = row?.querySelector<HTMLElement>("[data-avatar]");
      if (!row || !name) continue;
      const to = name.getBoundingClientRect();
      const copy = document.createElement("span");
      copy.textContent = from.label;
      copy.className =
        "absolute left-0 top-0 inline-flex h-7 items-center whitespace-nowrap rounded-full bg-background px-2.5 text-[13px] font-medium text-foreground shadow-[inset_0_0_0_1px_var(--border)] will-change-transform";
      layer.appendChild(copy);
      const x0 = from.rect.left - box.left;
      const y0 = from.rect.top - box.top + (from.rect.height - 28) / 2;
      const x1 = to.left - box.left - 10;
      const y1 = to.top - box.top + to.height / 2 - 14;
      const delay = i++ * 60;
      // Lift off, travel, then hand over to the row's own name: the copy blurs out as the name sharpens in.
      const flight = copy.animate(
        [
          {
            transform: `translate(${x0}px, ${y0}px)`,
            opacity: 1,
            filter: "blur(0px)",
            boxShadow: "inset 0 0 0 1px var(--border)",
            easing: "cubic-bezier(0.3,0,0.2,1)",
          },
          {
            transform: `translate(${x0}px, ${y0 - 6}px)`,
            opacity: 1,
            filter: "blur(0px)",
            offset: 0.14,
            easing: EASE,
          },
          {
            transform: `translate(${x1}px, ${y1}px)`,
            opacity: 1,
            filter: "blur(0px)",
            boxShadow: "inset 0 0 0 1px transparent",
            backgroundColor: "transparent",
            offset: 0.7,
            easing: "linear",
          },
          {
            transform: `translate(${x1}px, ${y1}px)`,
            opacity: 0,
            filter: "blur(4px)",
            boxShadow: "inset 0 0 0 1px transparent",
            backgroundColor: "transparent",
          },
        ],
        { duration: 680, delay, fill: "both" },
      );
      flight.onfinish = flight.oncancel = () => copy.remove();
      name.animate(
        [
          { opacity: 0, filter: "blur(4px)" },
          {
            opacity: 0,
            filter: "blur(4px)",
            offset: (delay + 680 * 0.66) / (delay + 680),
          },
          { opacity: 1, filter: "blur(0px)" },
        ],
        { duration: delay + 680, easing: "linear" },
      );
      avatar?.animate(
        [
          { opacity: 0, transform: "scale(0.6)", filter: "blur(3px)" },
          { opacity: 1, transform: "none", filter: "blur(0px)" },
        ],
        { duration: 420, delay: delay + 360, easing: EASE, fill: "backwards" },
      );
    }
  }, [members, reduced]);

  const count = valid.length;
  return (
    <div
      ref={rootRef}
      className={`@container relative w-full rounded-[22px] border border-border bg-background text-foreground ${className}`}
      {...props}
    >
      <div className="flex items-start justify-between gap-3 px-4 pt-4 pb-3.5 @md:px-5 @md:pt-5">
        <div className="min-w-0">
          <p className="flex items-baseline gap-2 text-[14px] font-medium tracking-[-0.01em]">
            {title}
            <span className="text-[12px] font-normal text-muted-foreground tabular-nums">
              <NumberRoll
                value={members.filter((m) => m.status !== "invited").length}
              />
            </span>
          </p>
          <p className="mt-0.5 text-[12px] text-muted-foreground">
            {description}
          </p>
        </div>
        {seats !== undefined && (
          <p
            className={`flex shrink-0 items-baseline whitespace-nowrap pt-0.5 text-[11.5px] tabular-nums transition-colors duration-300 ${left === 0 ? "text-amber-700 dark:text-amber-400" : "text-muted-foreground"}`}
          >
            <NumberRoll value={used} />
            &nbsp;of&nbsp;
            <NumberRoll value={seats} />
            &nbsp;<TextMorph>{seats === 1 ? "seat" : "seats"}</TextMorph>
          </p>
        )}
      </div>

      {onInvite && (
        <div ref={fieldRef} className="px-4 pb-4 @md:px-5">
          <TagInput
            value={tags}
            onValueChange={(next) => {
              setTags(next);
              setInviteError(null);
              if (sending !== "pending") setSending("idle");
            }}
            label="Invite by email"
            placeholder="Emails, separated by commas"
            hint={
              inviteError ??
              (left === 0
                ? "Every seat is taken. Remove someone or add seats to invite more."
                : "Paste a list or pick from your directory.")
            }
            validate={validate}
            normalize={lower}
            separators={SPLIT}
            suggestions={suggestions}
            createLabel={(text) => `Invite “${text}”`}
            max={left}
            limitMessage={
              left === 1
                ? "One seat left on your plan."
                : `${left} seats left on your plan.`
            }
            collapse={2}
            disabled={sending === "pending"}
          />
          <div className="mt-3 flex items-center justify-end gap-2">
            <RoleMenu
              roles={roles}
              value={role}
              onValueChange={setRole}
              label="Role for new members"
              prefix="as"
            />
            <StatusButton
              size="sm"
              status={sending}
              labels={{
                idle: count > 1 ? `Invite ${count}` : "Invite",
                pending: "Inviting",
                success: "Invited",
                error: "Try again",
              }}
              onClick={invite}
              onReset={() => setSending("idle")}
              aria-disabled={(!count && sending === "idle") || undefined}
              className={
                !count && sending === "idle"
                  ? "pointer-events-none opacity-50"
                  : ""
              }
            />
          </div>
        </div>
      )}

      <div className="relative border-t border-border">
        <ul ref={listRef} aria-label={title} className="relative">
          {members.map((m) => (
            <MemberRow
              key={m.id}
              m={m}
              roles={roles}
              saving={Boolean(saving[m.id])}
              shake={shakes[m.id] ?? 0}
              note={notes[m.id]}
              gone={gone.includes(m.id)}
              canEdit={Boolean(onRoleChange)}
              canRemove={Boolean(onRemove)}
              canResend={Boolean(onResend)}
              resendAfter={resendAfter}
              reduced={reduced}
              act={act}
            />
          ))}
        </ul>
        {/* Rows that went: their own elements, folding away where they stood (see use-row-motion). */}
        <div
          ref={ghostRef}
          aria-hidden="true"
          className="pointer-events-none absolute inset-0"
        />
      </div>

      {/* Chips on their way from the field to their rows. */}
      <div
        ref={flyRef}
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 z-20"
      />
      <span className="sr-only" role="status">
        {announce}
      </span>
    </div>
  );
}

"use client";

import * as React from "react";
import { StatusButton, type ActionStatus } from "./status-button";

/* ─────────────────────────────────────────────────────────
 * CONFIRM ACTION: an icon that asks before it acts
 *
 *   ask       a click and the icon's own circle stretches into
 *             a pill: the confirm button opens out to its left
 *             and the icon turns into a cross that takes it back
 *   act       the confirm button is a status button, so it says
 *             Revoking, Revoked or Try again in place
 *   leave     Escape, the cross, or a click or focus anywhere
 *             else folds it back into the icon
 *
 * Nothing opens over the row it belongs to; the question sits
 * where the icon was.
 * ───────────────────────────────────────────────────────── */

export interface ConfirmActionProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onClick"
> {
  icon: React.ReactNode;
  /** The icon button's accessible name, e.g. "Revoke Production key". */
  label: string;
  /** The confirm button's words per state, e.g. { idle: "Revoke", pending: "Revoking", success: "Revoked" }. */
  labels?: Partial<Record<ActionStatus, string>>;
  /** "danger" makes the confirm red. */
  tone?: "danger" | "default";
  /** Runs once on confirm. Throw (or reject) to show Try again. */
  onConfirm: () => Promise<unknown> | unknown;
  /** Back to the icon this long after success (ms); 0 keeps "done" until the row goes. */
  resetAfter?: number;
  disabled?: boolean;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Cross() {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className="size-3.5"
    >
      <path
        d="M4.5 4.5l7 7M11.5 4.5l-7 7"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
      />
    </svg>
  );
}

export function ConfirmAction({
  icon,
  label,
  labels,
  tone = "danger",
  onConfirm,
  resetAfter = 0,
  disabled = false,
  className = "",
  ...props
}: ConfirmActionProps) {
  const reduced = useReducedMotion();
  const [asking, setAsking] = React.useState(false);
  const [status, setStatus] = React.useState<ActionStatus>("idle");
  const wrapRef = React.useRef<HTMLDivElement>(null);
  const iconRef = React.useRef<HTMLButtonElement>(null);
  const run = React.useRef(0);
  const busy = status === "pending" || status === "success";

  const cancel = React.useCallback(
    (refocus: boolean) => {
      if (status === "pending") return;
      run.current++;
      setAsking(false);
      setStatus("idle");
      if (refocus) iconRef.current?.focus({ preventScroll: true });
    },
    [status],
  );

  // The question is open: its button takes focus once it's there to take it.
  React.useEffect(() => {
    if (asking && status === "idle")
      wrapRef.current
        ?.querySelector<HTMLButtonElement>("[data-confirm]")
        ?.focus({ preventScroll: true });
  }, [asking, status]);

  React.useEffect(() => {
    if (!asking) return;
    const onDown = (e: PointerEvent) => {
      if (!wrapRef.current?.contains(e.target as Node)) cancel(false);
    };
    document.addEventListener("pointerdown", onDown);
    return () => document.removeEventListener("pointerdown", onDown);
  }, [asking, cancel]);

  const confirm = async () => {
    if (busy) return;
    const mine = ++run.current;
    setStatus("pending");
    try {
      await onConfirm();
      if (run.current === mine) setStatus("success");
    } catch {
      if (run.current === mine) setStatus("error");
    }
  };

  const t = `${reduced ? 0 : 420}ms ${EASE}`;
  const red =
    tone === "danger"
      ? "text-red-600! hover:bg-red-500/10! dark:text-red-400!"
      : "";

  return (
    <div
      ref={wrapRef}
      className={`relative inline-flex h-7 shrink-0 items-center rounded-full ${className}`}
      onKeyDown={(e) => {
        if (e.key === "Escape" && asking) {
          e.preventDefault();
          e.stopPropagation();
          cancel(true);
        }
      }}
      onBlur={(e) => {
        if (
          asking &&
          !busy &&
          document.hasFocus() &&
          !wrapRef.current?.contains(e.relatedTarget as Node)
        )
          cancel(false);
      }}
      {...props}
    >
      {/* The icon's circle, stretched into the pill round the question. */}
      <span
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 rounded-full"
        style={{
          boxShadow: `inset 0 0 0 1px ${asking ? "var(--border)" : "transparent"}`,
          transition: `box-shadow ${t}`,
        }}
      />
      <span
        className="grid"
        inert={!asking}
        style={{
          gridTemplateColumns: asking ? "1fr" : "0fr",
          opacity: asking ? 1 : 0,
          filter: asking || reduced ? "none" : "blur(3px)",
          transition: `grid-template-columns ${t}, opacity ${reduced ? 0 : asking ? 320 : 160}ms ${EASE}, filter ${t}`,
        }}
      >
        <span className="min-w-0 overflow-hidden [clip-path:inset(-2px_0_-2px_0)]">
          <span className="flex w-max items-center pl-0.5">
            <StatusButton
              data-confirm=""
              size="sm"
              variant="ghost"
              status={status}
              labels={{
                idle: "Confirm",
                pending: "Working",
                success: "Done",
                error: "Try again",
                ...labels,
              }}
              onClick={confirm}
              onReset={resetAfter ? () => cancel(false) : undefined}
              resetAfter={resetAfter || undefined}
              className={`h-[26px]! ${status === "error" ? "" : red}`}
            />
          </span>
        </span>
      </span>
      <button
        ref={iconRef}
        type="button"
        aria-label={asking ? "Cancel" : label}
        aria-expanded={asking}
        disabled={disabled}
        onClick={() => (asking ? cancel(true) : setAsking(true))}
        className={`relative grid size-7 shrink-0 cursor-pointer place-items-center rounded-full text-muted-foreground transition-colors duration-150 hover:bg-accent hover:text-foreground disabled:cursor-default disabled:opacity-40 aria-disabled:cursor-default ${FOCUS}`}
        aria-disabled={busy || undefined}
      >
        {[icon, <Cross key="x" />].map((glyph, i) => {
          const on = (i === 1) === asking;
          return (
            <span
              key={i}
              aria-hidden="true"
              className="absolute inset-0 grid place-items-center [&_svg]:size-3.5"
              style={{
                opacity: on ? 1 : 0,
                transform: on ? "none" : "scale(0.6)",
                filter: on || reduced ? "none" : "blur(3px)",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, transform 380ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              {glyph}
            </span>
          );
        })}
      </button>
    </div>
  );
}

"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * STATUS BUTTON: a button that tells you what happened
 *
 *   idle     "Save", with an optional icon
 *   pending  a spinner opens in; the label morphs to "Saving"
 *   success  a check draws itself; "Saved"
 *   error    the button gives a small shake; "Try again"
 *
 * Every change is one motion: the icon slot opens and closes,
 * icons swap through a blur, letters the labels share stay put
 * and the button's width eases to fit.
 * ───────────────────────────────────────────────────────── */

export type ActionStatus = "idle" | "pending" | "success" | "error";

export interface StatusButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  status?: ActionStatus;
  /** Labels per state; defaults to Save, Saving, Saved, Try again. */
  labels?: Partial<Record<ActionStatus, string>>;
  /** Shown before the label while idle. */
  icon?: React.ReactNode;
  variant?: "primary" | "outline" | "ghost";
  /** "sm" is 28px tall, for toolbars and headers. */
  size?: "default" | "sm";
  /** Called this long after success (ms), e.g. to go back to idle. */
  onReset?: () => void;
  resetAfter?: number;
}

const LABELS: Record<ActionStatus, string> = {
  idle: "Save",
  pending: "Saving",
  success: "Saved",
  error: "Try again",
};
const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${EASE} 120ms`
              : "none",
        }}
      />
    </svg>
  );
}

function Alert() {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 4.75v3.75"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11" r="1" fill="currentColor" />
    </svg>
  );
}

export function StatusButton({
  status = "idle",
  labels,
  icon,
  variant = "primary",
  size = "default",
  onReset,
  resetAfter = 1800,
  className = "",
  onClick,
  ...props
}: StatusButtonProps) {
  const reduced = useReducedMotion();
  const ref = React.useRef<HTMLButtonElement>(null);
  const label = { ...LABELS, ...labels }[status];
  const showIcon = status !== "idle" || Boolean(icon);
  const busy = status === "pending";
  const sm = size === "sm";
  const iconSize = sm ? 14 : 16;

  // A short shake when it fails: the eye catches it even if you looked away.
  React.useEffect(() => {
    if (status !== "error" || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [status, reduced]);

  React.useEffect(() => {
    if (status !== "success" || !onReset) return;
    const timer = window.setTimeout(onReset, resetAfter);
    return () => window.clearTimeout(timer);
  }, [status, onReset, resetAfter]);

  const tone =
    status === "error"
      ? "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400"
      : variant === "primary"
        ? "bg-primary text-primary-foreground hover:bg-primary/90"
        : variant === "ghost"
          ? `hover:bg-accent hover:text-foreground ${status === "idle" ? "text-muted-foreground" : "text-foreground"}`
          : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent";

  const icons: Record<ActionStatus, React.ReactNode> = {
    idle: icon,
    // Spins only while pending, so a hidden spinner never keeps the page busy.
    pending: (
      <span
        className={`${sm ? "size-3" : "size-3.5"} rounded-full border-[1.5px] border-current border-t-transparent opacity-80 motion-reduce:animate-none ${status === "pending" ? "animate-spin" : ""}`}
      />
    ),
    success: <Check drawn={status === "success"} reduced={reduced} />,
    error: <Alert />,
  };

  return (
    <>
      <button
        ref={ref}
        type="button"
        aria-busy={busy || undefined}
        aria-disabled={busy || undefined}
        onClick={(e) => {
          if (busy) return e.preventDefault();
          onClick?.(e);
        }}
        className={`cursor-pointer disabled:cursor-default aria-disabled:cursor-default inline-flex items-center justify-center whitespace-nowrap rounded-full font-medium transition-[background-color,color,box-shadow,scale,padding] duration-300 active:scale-[0.97] motion-reduce:active:scale-100 ${
          sm
            ? `h-7 text-[12px] ${variant === "ghost" ? "px-2.5" : "px-3"}`
            : "h-9 px-4 text-[13px]"
        } ${FOCUS} ${tone} ${className}`}
        {...props}
      >
        <span
          aria-hidden="true"
          className={`relative flex shrink-0 items-center justify-center ${sm ? "h-3.5 [&_svg]:size-3.5" : "h-4 [&_svg]:size-4"}`}
          style={{
            width: showIcon ? iconSize : 0,
            marginRight: showIcon ? (sm ? 5 : 6) : 0,
            transition: reduced
              ? "none"
              : `width 380ms ${EASE}, margin 380ms ${EASE}`,
          }}
        >
          {(Object.keys(icons) as ActionStatus[]).map((s) => (
            <span
              key={s}
              className="absolute inset-0 flex items-center justify-center"
              style={{
                opacity: s === status ? 1 : 0,
                transform: s === status ? "none" : "scale(0.6)",
                filter: s === status ? "none" : "blur(3px)",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, transform 380ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              {icons[s]}
            </span>
          ))}
        </span>
        <TextMorph>{label}</TextMorph>
      </button>
      {/* Outside the button, so the announcement isn't read as part of its name. */}
      <span className="sr-only" role="status">
        {status === "idle" ? "" : label}
      </span>
    </>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * RELATIVE TIME: "2 min ago" that keeps itself true
 *
 *   tick      it re-renders only when the words would change:
 *             on the next minute under an hour, the next hour
 *             under a day; nothing runs between
 *   roll      the number rolls up ("2 min" → "3 min") and the
 *             unit morphs when it changes ("59 min" → "1 h")
 *   date      past a week it settles on the date ("12 Sep")
 *
 * Until it's mounted it renders the date, so the server and the
 * first paint agree; the hover title is always the full time.
 * ───────────────────────────────────────────────────────── */

export type DateLike = Date | string | number;

export interface RelativeTimeProps extends Omit<
  React.HTMLAttributes<HTMLElement>,
  "children"
> {
  date: DateLike;
  /** Said before the time, e.g. "Last used". */
  prefix?: string;
  /** Under a minute. */
  justNow?: string;
  locales?: string | string[];
}

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

export const toTime = (d: DateLike) =>
  d instanceof Date
    ? d.getTime()
    : typeof d === "number"
      ? d
      : new Date(d).getTime();

const MONTHS = [
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
];

/** "12 Sep", with the year when it isn't this one; pass locales to use the browser's own format. */
export function formatDate(d: DateLike, locales?: string | string[]) {
  const t = new Date(toTime(d));
  const sameYear = t.getFullYear() === new Date().getFullYear();
  if (locales)
    return t.toLocaleDateString(
      locales,
      sameYear
        ? { day: "numeric", month: "short" }
        : { day: "numeric", month: "short", year: "numeric" },
    );
  return `${t.getDate()} ${MONTHS[t.getMonth()]}${sameYear ? "" : ` ${t.getFullYear()}`}`;
}

type Parts = { n: number | null; unit: string; next: number };

function parts(
  at: number,
  now: number,
  justNow: string,
  locales?: string | string[],
): Parts {
  const ago = Math.max(0, now - at);
  if (ago < MINUTE) return { n: null, unit: justNow, next: MINUTE - ago };
  if (ago < HOUR)
    return {
      n: Math.floor(ago / MINUTE),
      unit: "min ago",
      next: MINUTE - (ago % MINUTE),
    };
  if (ago < DAY) {
    const h = Math.floor(ago / HOUR);
    return {
      n: h,
      unit: h === 1 ? "hour ago" : "hours ago",
      next: HOUR - (ago % HOUR),
    };
  }
  if (ago < 7 * DAY) {
    const d = Math.floor(ago / DAY);
    return {
      n: d,
      unit: d === 1 ? "day ago" : "days ago",
      next: DAY - (ago % DAY),
    };
  }
  return { n: null, unit: formatDate(at, locales), next: 0 };
}

const subscribeMounted = () => () => {};

export function RelativeTime({
  date,
  prefix,
  justNow = "just now",
  locales,
  className = "",
  ...props
}: RelativeTimeProps) {
  const at = toTime(date);
  const mounted = React.useSyncExternalStore(
    subscribeMounted,
    () => true,
    () => false,
  );
  const [now, setNow] = React.useState(() => Date.now());
  const p = parts(at, mounted ? now : at + 8 * DAY, justNow, locales);

  // One timer, set for the moment the words change.
  React.useEffect(() => {
    if (!mounted || !p.next) return;
    const timer = window.setTimeout(() => setNow(Date.now()), p.next + 50);
    return () => window.clearTimeout(timer);
  }, [mounted, p.next, now]);

  React.useEffect(() => {
    const timer = window.setTimeout(() => setNow(Date.now()), 0);
    return () => window.clearTimeout(timer);
  }, [at]);

  const iso = new Date(at).toISOString();
  return (
    <time
      dateTime={iso}
      title={new Date(at).toLocaleString(locales ?? "en-GB", {
        dateStyle: "medium",
        timeStyle: "short",
      })}
      className={`inline-flex items-baseline whitespace-nowrap tabular-nums ${className}`}
      {...props}
    >
      {prefix && <span>{prefix}&nbsp;</span>}
      {/* Remounted once on the client, so the first real words appear without a morph. */}
      <Words key={mounted ? "client" : "server"} n={p.n} unit={p.unit} />
    </time>
  );
}

function Words({ n, unit }: { n: number | null; unit: string }) {
  return (
    <>
      <span
        aria-hidden={n === null || undefined}
        className="inline-grid transition-[grid-template-columns] duration-[380ms] ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:transition-none"
        style={{ gridTemplateColumns: n === null ? "0fr" : "1fr" }}
      >
        <span className="min-w-0 [clip-path:inset(-4px_0)]">
          <span className="inline-flex items-baseline pr-[0.25em]">
            <NumberRoll value={n ?? 1} direction="up" />
          </span>
        </span>
      </span>
      <TextMorph>{unit}</TextMorph>
    </>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";
import {
  carryFrames,
  flyFrames,
  LEAVE_FRAMES,
  playTokens,
  pulseToken,
  shakeToken,
  snapshotTokens,
  TOKEN_EASE,
  type TokenBox,
  type TokenEnter,
  type TokenSnapshot,
} from "./use-token-flip";

/* ─────────────────────────────────────────────────────────
 * TAG INPUT: the To field, the invite field, the labels field
 *
 *   type      Enter or a comma, and the letters you typed stay
 *             where they are while a thin line shell grows round
 *             them; the caret is already past it
 *   paste     a pasted list spills out of the caret chip by
 *             chip; a duplicate flies into its twin, which
 *             bumps; an invalid one lands red and shakes
 *   resolve   "maya@fernhill.co" morphs into "Maya Chen" while
 *             her initials open in, once resolve() knows her
 *   pick      a suggestion's name is carried from the list
 *             into its chip
 *   back      Backspace in an empty field selects the last
 *             chip; again, and its shell drops away and the
 *             letters are text you can edit
 *   reflow    every chip glides when one leaves or a line
 *             wraps; the field's height eases to fit
 *   collapse  out of focus, lines past `collapse` fold away and
 *             a "+4" counts them
 * ───────────────────────────────────────────────────────── */

export interface TagInputTag {
  id: string;
  /** What was typed or picked, normalised: the address, the label. */
  value: string;
  /** What the chip shows instead, once known: a name for an address. */
  label?: string;
  /** A picture for the chip. Without one, a known label gets its initials. */
  image?: string;
  /** Why the value isn't valid. The chip turns red and stays until it's fixed or removed. */
  error?: string;
}

export interface TagInputSuggestion {
  value: string;
  label?: string;
  image?: string;
  /** A second line in the list; defaults to the value when a label is shown. */
  description?: string;
}

export interface TagInputHandle {
  /** Runs text through the paste path: split, checked and cascaded in. */
  paste: (text: string) => void;
  focus: () => void;
  /** Removes every tag. */
  clear: () => void;
}

export interface TagInputProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "defaultValue" | "onChange"
> {
  value?: TagInputTag[];
  defaultValue?: TagInputTag[];
  onValueChange?: (tags: TagInputTag[]) => void;
  /** Return a message to mark a value invalid. */
  validate?: (value: string) => string | null | undefined | void;
  /** Look a value up once it's added: resolve to a label (and image) for the chip to morph into, or null to leave it. */
  resolve?: (
    value: string,
  ) => Promise<{ label?: string; image?: string } | null | undefined | void>;
  /** A list to filter, or a function that finds matches for what's typed (may be async). */
  suggestions?:
    | TagInputSuggestion[]
    | ((query: string) => TagInputSuggestion[] | Promise<TagInputSuggestion[]>);
  /** Applied to every value before it's checked and compared, e.g. lower-casing addresses. */
  normalize?: (value: string) => string;
  /** What splits typed and pasted text into values. */
  separators?: RegExp;
  /** How many tags the field takes. */
  max?: number;
  /** Shown when a value doesn't fit under `max`. */
  limitMessage?: string;
  /** The suggestion row that adds what's typed as it is; null hides it. */
  createLabel?: ((text: string) => string) | null;
  /** Lines to show while the field is out of focus; the rest fold into a count. */
  collapse?: number;
  /** Accessible name of the field. */
  label?: string;
  placeholder?: string;
  /** A line under the field, replaced by errors and notices while they last. */
  hint?: string;
  /** Submits the valid values, comma-separated, with a form. */
  name?: string;
  disabled?: boolean;
  ref?: React.Ref<TagInputHandle>;
}

type Draft = { value: string; label?: string; image?: string };
type Ghost = {
  key: number;
  kind: "leave" | "fly" | "unspool" | "carry";
  text: string;
  /** Root coordinates. */
  box: TokenBox;
  to?: TokenBox;
  /** Where the letters sit inside the box. */
  inner?: TokenBox;
  twin?: string;
  delay?: number;
  /** Fades in where it starts (a pasted duplicate) instead of already being there. */
  appear?: boolean;
  error?: boolean;
  avatar?: { image?: string; name: string };
};
/** A copy flying to a chip whose place is only known after layout; `after` starts it where it would have landed, after that chip. */
type Flight = {
  kind: "fly" | "carry";
  text: string;
  from: TokenBox | { after: string | null; w: number };
  twin: string;
  delay: number;
};
type Pending = {
  before: TokenSnapshot | null;
  enter: Map<string, TokenEnter>;
  skipInput?: boolean;
  ghosts: Ghost[];
  /** Ghosts flying to a chip whose place is only known after layout. */
  flights: Flight[];
  shake: { id: string; delay: number }[];
  shakeField?: boolean;
  /** Edited text glides out of this box (root coordinates) into the input. */
  inputFrom?: { box: TokenBox; fade: boolean };
  focus?: "input" | string;
};
type Notice = { text: string; tone: "muted" | "warn"; key: number };
type Row = TagInputSuggestion & { create?: boolean };
type How =
  | { type: TokenBox | null }
  | { paste: { x: number; y: number } }
  | { pick: TokenBox };

const EASE = TOKEN_EASE;
const EMPTY: TagInputTag[] = [];
const SEPARATORS = /[,;\n]+/;
const CHIP_H = 28;
/** Labels longer than this many characters are cut to fit a phone-width field; the chip's title has the whole. */
const LONG = 28;
const PAD = 5;
const GAP = 6;
const CREATE = (text: string) => `Add “${text}”`;
const SAME = (v: string) => v;

let seq = 0;
const newId = () => `tag-${Date.now().toString(36)}-${(seq++).toString(36)}`;
const display = (t: { value: string; label?: string }) => t.label || t.value;
const initials = (name: string) =>
  name
    .split(/[\s._-]+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((w) => w[0]!.toUpperCase())
    .join("");
const shift = (b: TokenBox, dx: number, dy: number): TokenBox => ({
  x: b.x + dx,
  y: b.y + dy,
  w: b.w,
  h: b.h,
});

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 240ms ${EASE}, transform 380ms ${EASE}, filter 240ms ${EASE}`,
});

const shellStyle = (
  error: boolean,
  selected: boolean,
): React.CSSProperties => ({
  background: error
    ? "color-mix(in oklab, #ef4444 7%, var(--background))"
    : selected
      ? "var(--accent)"
      : "var(--background)",
  boxShadow: error
    ? `inset 0 0 0 1px color-mix(in oklab, #ef4444 ${selected ? 75 : 45}%, transparent)`
    : selected
      ? "inset 0 0 0 1px color-mix(in oklab, var(--ring) 70%, transparent)"
      : "inset 0 0 0 1px var(--border)",
});

function Avatar({
  image,
  name,
  size,
}: {
  image?: string;
  name: string;
  size: number;
}) {
  return image ? (
    <img
      src={image}
      alt=""
      draggable={false}
      className="shrink-0 rounded-full object-cover"
      style={{ width: size, height: size }}
    />
  ) : (
    <span
      className="flex shrink-0 items-center justify-center rounded-full bg-muted font-medium text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]"
      style={{ width: size, height: size, fontSize: Math.round(size * 0.4) }}
    >
      {initials(name)}
    </span>
  );
}

function Cross() {
  return (
    <svg viewBox="0 0 12 12" className="size-3" fill="none" aria-hidden="true">
      <path
        d="M3.5 3.5 8.5 8.5M8.5 3.5 3.5 8.5"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="round"
      />
    </svg>
  );
}

/** A sentence that changes crossfades whole: the old one lifts away through a blur while the new one rises in. */
function Line({ text, reduced }: { text: string; reduced: boolean }) {
  const [shown, setShown] = React.useState({ text, key: 0 });
  const [leaving, setLeaving] = React.useState<{ text: string; key: number }[]>(
    [],
  );
  if (text !== shown.text) {
    if (shown.text && !reduced) setLeaving((l) => [...l, shown]);
    setShown({ text, key: shown.key + 1 });
  }
  return (
    <span className="relative block">
      <span
        key={shown.key}
        className="block"
        ref={(el) => {
          if (!el || reduced || shown.key === 0 || el.dataset.in) return;
          el.dataset.in = "1";
          el.animate(
            [
              {
                opacity: 0,
                transform: "translateY(0.35em)",
                filter: "blur(4px)",
              },
              { opacity: 1, transform: "none", filter: "blur(0px)" },
            ],
            { duration: 420, delay: 60, easing: EASE, fill: "backwards" },
          );
        }}
      >
        {shown.text || " "}
      </span>
      {leaving.map((l) => (
        <span
          key={l.key}
          aria-hidden="true"
          className="pointer-events-none absolute inset-x-0 top-0 block"
          ref={(el) => {
            if (!el || el.dataset.out) return;
            el.dataset.out = "1";
            el.animate(
              [
                { opacity: 1, transform: "none", filter: "blur(0px)" },
                {
                  opacity: 0,
                  transform: "translateY(-0.35em)",
                  filter: "blur(4px)",
                },
              ],
              { duration: 200, easing: EASE, fill: "forwards" },
            ).onfinish = () =>
              setLeaving((all) => all.filter((x) => x.key !== l.key));
          }}
        >
          {l.text}
        </span>
      ))}
    </span>
  );
}

/** A copy of a chip (or of its letters) that leaves, flies into a twin, drops its shell or carries a name in. */
function GhostChip({
  ghost,
  onDone,
}: {
  ghost: Ghost;
  onDone: (ghost: Ghost) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  const shell = React.useRef<HTMLSpanElement>(null);
  const letters = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    let a: Animation;
    if (ghost.kind === "leave")
      a = el.animate(LEAVE_FRAMES, {
        duration: 280,
        easing: EASE,
        fill: "forwards",
      });
    else if (ghost.kind === "fly" && ghost.to)
      a = el.animate(flyFrames(ghost.box, ghost.to, ghost.appear), {
        duration: ghost.appear ? 820 : 620,
        delay: ghost.delay ?? 0,
        easing: EASE,
        fill: "both",
      });
    else if (ghost.kind === "carry" && ghost.to)
      a = el.animate(carryFrames(ghost.box, ghost.to), {
        duration: 480,
        easing: EASE,
        fill: "both",
      });
    else {
      // The shell shrinks round the letters and fades; the letters fade into the input's own.
      const b = ghost.box;
      const i = ghost.inner ?? b;
      const left = Math.max(0, i.x - b.x - 3);
      const right = Math.max(0, b.x + b.w - (i.x + i.w) - 3);
      shell.current?.animate(
        [
          { clipPath: "inset(0px 0px 0px 0px round 999px)", opacity: 1 },
          {
            clipPath: `inset(4px ${right}px 4px ${left}px round 999px)`,
            opacity: 0,
          },
        ],
        { duration: 360, easing: EASE, fill: "forwards" },
      );
      el.querySelector<HTMLElement>("[data-ghost-avatar]")?.animate(
        LEAVE_FRAMES,
        { duration: 240, easing: EASE, fill: "forwards" },
      );
      a = (letters.current ?? el).animate(
        [
          { opacity: 1, filter: "blur(0px)" },
          { opacity: 0, filter: "blur(4px)" },
        ],
        { duration: 320, easing: EASE, fill: "forwards" },
      );
    }
    a.onfinish = () => onDone(ghost);
    return () => a.cancel();
  }, []);

  const carry = ghost.kind === "carry";
  const inner = ghost.inner;
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className={`pointer-events-none absolute flex items-center whitespace-nowrap will-change-transform ${carry ? "text-[13.5px]" : "rounded-full px-2.5 text-[13px]"} ${
        ghost.error ? "text-red-600 dark:text-red-400" : "text-foreground"
      }`}
      style={{
        left: ghost.box.x,
        top: ghost.box.y,
        width: ghost.box.w,
        height: ghost.box.h,
        transformOrigin: carry ? "left center" : "center",
      }}
    >
      {!carry && (
        <span
          ref={shell}
          className="absolute inset-0 rounded-full"
          style={shellStyle(!!ghost.error, false)}
        />
      )}
      {ghost.avatar && (
        <span data-ghost-avatar="" className="absolute left-1 top-1">
          <Avatar
            image={ghost.avatar.image}
            name={ghost.avatar.name}
            size={20}
          />
        </span>
      )}
      <span
        ref={letters}
        className={inner ? "absolute block py-1" : "relative"}
        style={
          inner
            ? { left: inner.x - ghost.box.x, top: inner.y - ghost.box.y }
            : undefined
        }
      >
        {ghost.text}
      </span>
    </span>
  );
}

export function TagInput({
  value,
  defaultValue,
  onValueChange,
  validate,
  resolve,
  suggestions,
  normalize = SAME,
  separators = SEPARATORS,
  max,
  limitMessage = "No room for more",
  createLabel = CREATE,
  collapse,
  label = "Add tags",
  placeholder,
  hint,
  name,
  disabled = false,
  ref,
  className = "",
  ...props
}: TagInputProps) {
  const reduced = useReducedMotion();
  const uid = React.useId();
  const [own, setOwn] = React.useState<TagInputTag[]>(defaultValue ?? EMPTY);
  const tags = value ?? own;
  const tagsRef = React.useRef(tags);
  const [text, setText] = React.useState("");
  const [resolving, setResolving] = React.useState<ReadonlySet<string>>(
    () => new Set(),
  );
  const [selected, setSelected] = React.useState<string | null>(null);
  const [within, setWithin] = React.useState(false);
  const [inputFocus, setInputFocus] = React.useState(false);
  const [asyncOptions, setAsyncOptions] = React.useState<TagInputSuggestion[]>(
    [],
  );
  const [active, setActive] = React.useState(-1);
  const [dismissed, setDismissed] = React.useState(false);
  const [notice, setNotice] = React.useState<Notice | null>(null);
  const [ghosts, setGhosts] = React.useState<Ghost[]>([]);
  const [announce, setAnnounce] = React.useState("");
  const [tick, setTick] = React.useState(0);
  const [cut, setCut] = React.useState<{
    hidden: string[];
    x: number;
    y: number;
    height: number;
  } | null>(null);
  const pending = React.useRef<Pending | null>(null);
  const rootRef = React.useRef<HTMLDivElement>(null);
  const fieldRef = React.useRef<HTMLDivElement>(null);
  const wrapRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLDivElement>(null);
  const inputRef = React.useRef<HTMLInputElement>(null);
  const mirrorRef = React.useRef<HTMLSpanElement>(null);
  const pillRef = React.useRef<HTMLSpanElement>(null);
  const rowRefs = React.useRef<(HTMLDivElement | null)[]>([]);
  const ghostKey = React.useRef(0);
  /** Focus we moved ourselves (after an edit or a removal) doesn't open the suggestions. */
  const quietFocus = React.useRef(false);
  /** Whether the chip being clicked was already selected: a second click (or tap) edits it. */
  const wasSelected = React.useRef(false);
  const alive = React.useRef(true);
  React.useEffect(() => {
    alive.current = true;
    return () => {
      alive.current = false;
    };
  }, []);

  const collapsed = collapse !== undefined && !within && tags.length > 0;
  const collapsedRef = React.useRef(collapsed);
  React.useLayoutEffect(() => {
    tagsRef.current = tags;
    collapsedRef.current = collapsed;
  });

  const commit = (next: TagInputTag[]) => {
    tagsRef.current = next;
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  };

  const say = (message: string) =>
    setAnnounce((a) => (a === message ? `${message} ` : message));
  const flashSeq = React.useRef(0);
  const flash = (message: string, tone: Notice["tone"]) => {
    const key = ++flashSeq.current;
    setNotice({ text: message, tone, key });
    window.setTimeout(
      () => setNotice((n) => (n?.key === key ? null : n)),
      2600,
    );
  };

  // ── Measuring ──────────────────────────────────────────
  /** From list coordinates to the root's, where ghosts live. */
  const rootOffset = () => {
    const list = listRef.current?.getBoundingClientRect();
    const root = rootRef.current?.getBoundingClientRect();
    return list && root
      ? { dx: list.left - root.left, dy: list.top - root.top }
      : { dx: 0, dy: 0 };
  };
  const textWidth = (s: string) => {
    const m = mirrorRef.current;
    if (!m) return s.length * 7;
    m.textContent = s;
    return m.offsetWidth;
  };
  /** Where a stretch of the input's text is drawn, in list coordinates. */
  const textBox = (start: number, s: string): TokenBox | null => {
    const input = inputRef.current;
    const list = listRef.current;
    if (!input || !list) return null;
    const i = input.getBoundingClientRect();
    const l = list.getBoundingClientRect();
    const h = 18;
    return {
      x:
        i.left -
        l.left +
        textWidth(input.value.slice(0, start)) -
        input.scrollLeft,
      y: i.top - l.top + (i.height - h) / 2,
      w: Math.max(1, textWidth(s)),
      h,
    };
  };
  const caretPoint = () => {
    const input = inputRef.current;
    const b = textBox(input?.selectionStart ?? text.length, "") ?? {
      x: PAD,
      y: PAD,
      w: 1,
      h: 18,
    };
    return { x: b.x, y: b.y + b.h / 2 - CHIP_H / 2 };
  };

  // ── Changes ────────────────────────────────────────────
  /** Queue a change to play after React lays it out. Changes in the same render merge; the earliest snapshot wins. */
  const stage = (p: Partial<Pending>, before?: TokenSnapshot | null) => {
    const prev = pending.current;
    pending.current = {
      ...prev,
      ...p,
      before: prev
        ? prev.before
        : (before ??
          (listRef.current ? snapshotTokens(listRef.current) : null)),
      enter: new Map([...(prev?.enter ?? []), ...(p.enter ?? [])]),
      ghosts: [...(prev?.ghosts ?? []), ...(p.ghosts ?? [])],
      flights: [...(prev?.flights ?? []), ...(p.flights ?? [])],
      shake: [...(prev?.shake ?? []), ...(p.shake ?? [])],
    };
    setTick((t) => t + 1);
  };

  const plan = (drafts: Draft[], base: TagInputTag[]) => {
    const next = base.slice();
    const added: TagInputTag[] = [];
    const dups: {
      draft: Draft;
      twin: string;
      index: number;
      after: string | null;
    }[] = [];
    let overflow = 0;
    let index = 0;
    for (const d of drafts) {
      const v = normalize(d.value.trim());
      if (!v) continue;
      const twin = next.find((t) => t.value === v);
      if (twin) {
        dups.push({
          draft: { ...d, value: v },
          twin: twin.id,
          index: index++,
          after: next[next.length - 1]?.id ?? null,
        });
        continue;
      }
      index++;
      if (max !== undefined && next.length >= max) {
        overflow++;
        continue;
      }
      const error = (validate?.(v) as string | null | undefined) || undefined;
      const tag: TagInputTag = {
        id: newId(),
        value: v,
        ...(d.label ? { label: d.label } : {}),
        ...(d.image ? { image: d.image } : {}),
        ...(error ? { error } : {}),
      };
      next.push(tag);
      added.push(tag);
    }
    return { next, added, dups, overflow };
  };

  const lookUp = (added: TagInputTag[]) => {
    if (!resolve) return;
    const run = added.filter((t) => !t.error && !t.label);
    if (!run.length) return;
    setResolving((s) => new Set([...s, ...run.map((t) => t.id)]));
    for (const tag of run) {
      Promise.resolve()
        .then(() => resolve(tag.value))
        .catch(() => null)
        .then((result) => {
          if (!alive.current) return;
          const found = result as
            { label?: string; image?: string } | null | undefined;
          const fill =
            found && (found.label || found.image)
              ? {
                  ...(found.label ? { label: found.label } : {}),
                  ...(found.image ? { image: found.image } : {}),
                }
              : null;
          const current = tagsRef.current;
          stage({});
          setResolving((s) => {
            const n = new Set(s);
            n.delete(tag.id);
            return n;
          });
          if (fill && current.some((t) => t.id === tag.id)) {
            commit(
              current.map((t) => (t.id === tag.id ? { ...t, ...fill } : t)),
            );
            if (fill.label) say(`${tag.value} is ${fill.label}.`);
          }
        });
    }
  };

  /** Adds values however they came: typed (the letters stay put), pasted (they spill from the caret) or picked (carried from the list). */
  const add = (drafts: Draft[], how: How) => {
    const result = plan(drafts, tagsRef.current);
    const { dx, dy } = rootOffset();
    const delayOf = (i: number) => ("paste" in how ? Math.min(i * 50, 500) : 0);
    const enter = new Map<string, TokenEnter>();
    const shake: Pending["shake"] = [];
    const flights: Flight[] = [];

    result.added.forEach((t, i) => {
      if ("type" in how)
        enter.set(
          t.id,
          how.type ? { from: "text", box: how.type } : { from: "text" },
        );
      else if ("paste" in how)
        enter.set(t.id, {
          from: "point",
          x: how.paste.x,
          y: how.paste.y,
          delay: delayOf(i),
        });
      else {
        enter.set(t.id, { from: "text", hold: 480 });
        flights.push({
          kind: "carry",
          text: display(t),
          from: how.pick,
          twin: t.id,
          delay: 0,
        });
      }
      if (t.error) shake.push({ id: t.id, delay: delayOf(i) + 380 });
    });

    result.dups.forEach((d) => {
      const word = display(d.draft);
      const w = textWidth(word) * (13 / 14) + 20;
      // A typed or picked repeat leaves from where it was; a pasted one turns up, in its turn, where it would have gone.
      const from =
        "pick" in how
          ? {
              x: how.pick.x - 10,
              y: how.pick.y + how.pick.h / 2 - CHIP_H / 2,
              w,
              h: CHIP_H,
            }
          : "paste" in how
            ? { after: d.after, w }
            : how.type
              ? {
                  x: how.type.x - 10 + dx,
                  y: how.type.y + how.type.h / 2 - CHIP_H / 2 + dy,
                  w,
                  h: CHIP_H,
                }
              : { x: dx, y: dy, w, h: CHIP_H };
      flights.push({
        kind: "fly",
        text: word,
        from,
        twin: d.twin,
        delay: delayOf(d.index),
      });
    });

    stage({
      enter,
      shake,
      flights,
      skipInput: "type" in how && !!how.type,
      shakeField: result.overflow > 0,
    });
    if (result.added.length) commit(result.next);
    // The list stays closed until you type again.
    setDismissed(true);
    lookUp(result.added);

    if (result.overflow) flash(limitMessage, "warn");
    else if (result.dups.length)
      flash(
        result.dups.length === 1
          ? `${display(result.dups[0].draft)} is already here`
          : `${result.dups.length} were already here`,
        "muted",
      );
    const invalid = result.added.filter((t) => t.error).length;
    say(
      [
        result.added.length === 1
          ? `Added ${display(result.added[0])}.`
          : result.added.length
            ? `Added ${result.added.length}.`
            : "",
        invalid ? `${invalid} not valid.` : "",
        result.dups.length ? `${result.dups.length} already added.` : "",
        result.overflow ? `${limitMessage}.` : "",
      ]
        .filter(Boolean)
        .join(" "),
    );
  };

  /** The typed text becomes a chip where it stands. */
  const commitText = (raw = text) => {
    const words = raw.split(separators).filter((w) => w.trim());
    if (!words.length) return;
    if (words.length > 1) {
      const point = caretPoint();
      setText("");
      add(
        words.map((w) => ({ value: w })),
        { paste: point },
      );
      return;
    }
    const lead = raw.length - raw.trimStart().length;
    const box = raw === text ? textBox(lead, words[0].trim()) : null;
    setText("");
    add([{ value: words[0] }], { type: box });
  };

  const pasteText = (pasted: string, start: number, end: number) => {
    const combined = text.slice(0, start) + pasted + text.slice(end);
    const point = caretPoint();
    setText("");
    add(
      combined.split(separators).map((w) => ({ value: w })),
      { paste: point },
    );
  };

  const ghostOf = (
    t: TagInputTag,
    kind: Ghost["kind"],
    snap: TokenSnapshot,
  ): Ghost | null => {
    const was = snap.chips.get(t.id);
    if (!was) return null;
    const { dx, dy } = rootOffset();
    const named = !!t.label && t.label !== t.value;
    return {
      key: ++ghostKey.current,
      kind,
      text: display(t),
      box: shift(was.screen, dx, dy),
      inner: shift(was.screenLabel, dx, dy),
      error: !!t.error,
      avatar:
        !t.error && (t.image || named)
          ? { image: t.image, name: display(t) }
          : undefined,
    };
  };

  const remove = (id: string, focus?: "input" | string) => {
    const tag = tagsRef.current.find((t) => t.id === id);
    const list = listRef.current;
    if (!tag || !list || disabled) return;
    const before = snapshotTokens(list);
    const ghost = ghostOf(tag, "leave", before);
    stage({ ghosts: ghost ? [ghost] : [], focus }, before);
    commit(tagsRef.current.filter((t) => t.id !== id));
    say(`Removed ${display(tag)}.`);
  };

  /** Back to text: the shell drops away and its letters become what you're typing. */
  const edit = (id: string) => {
    const tag = tagsRef.current.find((t) => t.id === id);
    const list = listRef.current;
    if (!tag || !list || disabled) return;
    const before = snapshotTokens(list);
    const ghost = ghostOf(tag, "unspool", before);
    // Anything already typed becomes chips first.
    const typed = plan(
      text
        .split(separators)
        .filter((w) => w.trim())
        .map((w) => ({ value: w })),
      tagsRef.current.filter((t) => t.id !== id),
    );
    stage(
      {
        ghosts: ghost ? [ghost] : [],
        skipInput: true,
        inputFrom: ghost?.inner
          ? { box: ghost.inner, fade: display(tag) !== tag.value }
          : undefined,
        focus: "input",
      },
      before,
    );
    commit(typed.next);
    lookUp(typed.added);
    setText(tag.value);
    setDismissed(true);
    say(`Editing ${tag.value}.`);
  };

  const clear = () => {
    const list = listRef.current;
    if (!list || !tagsRef.current.length) return;
    const before = snapshotTokens(list);
    stage(
      {
        ghosts: tagsRef.current.flatMap(
          (t) => ghostOf(t, "leave", before) ?? [],
        ),
      },
      before,
    );
    commit([]);
    say("Cleared.");
  };

  React.useImperativeHandle(ref, () => ({
    paste: (s: string) => pasteText(s, text.length, text.length),
    focus: () => inputRef.current?.focus(),
    clear,
  }));

  // ── Height and collapse ────────────────────────────────
  const measure = React.useCallback(() => {
    const list = listRef.current;
    const wrap = wrapRef.current;
    if (!list || !wrap) return;
    let next: typeof cut = null;
    if (collapsedRef.current && collapse !== undefined) {
      const chips = Array.from(
        list.querySelectorAll<HTMLElement>("[data-token]"),
      );
      const lines = [...new Set(chips.map((c) => c.offsetTop))].sort(
        (a, b) => a - b,
      );
      if (lines.length > collapse) {
        const last = lines[Math.max(0, collapse - 1)];
        const limit =
          list.clientWidth - PAD - (pillRef.current?.offsetWidth ?? 40) - GAP;
        const hidden: string[] = [];
        let x = PAD;
        for (const c of chips) {
          if (c.offsetTop < last) continue;
          if (
            c.offsetTop === last &&
            !hidden.length &&
            c.offsetLeft + c.offsetWidth <= limit
          )
            x = c.offsetLeft + c.offsetWidth + GAP;
          else hidden.push(c.dataset.token!);
        }
        next = { hidden, x, y: last, height: last + CHIP_H + PAD };
      }
    }
    setCut((c) =>
      c === next ||
      (c &&
        next &&
        c.x === next.x &&
        c.y === next.y &&
        c.height === next.height &&
        c.hidden.join() === next.hidden.join())
        ? c
        : next,
    );
    const target = `${next ? next.height : list.offsetHeight}px`;
    if (wrap.style.height !== target) {
      wrap.style.transition =
        wrap.dataset.ready && !reduced ? `height 420ms ${EASE}` : "none";
      wrap.style.height = target;
      wrap.dataset.ready = "1";
    }
  }, [collapse, reduced]);

  // ── Playing a change ───────────────────────────────────
  // TextMorph commits a label's new letters one render after it gets the text, so measure one render later (still before
  // paint): otherwise a chip that resolves to a shorter name would change width after the glide was measured.
  const [playTick, setPlayTick] = React.useState(0);
  React.useLayoutEffect(() => {
    if (pending.current) setPlayTick((t) => t + 1);
  }, [tick]);
  React.useLayoutEffect(() => {
    const p = pending.current;
    const list = listRef.current;
    if (!p || !list) return;
    pending.current = null;
    const after = p.before
      ? playTokens(list, p.before, {
          enter: p.enter,
          skipInput: p.skipInput,
          reduced,
        })
      : snapshotTokens(list);
    const chip = (id: string) =>
      list.querySelector<HTMLElement>(`[data-token="${CSS.escape(id)}"]`);
    p.shake.forEach((s) => shakeToken(chip(s.id), reduced, s.delay));
    if (p.shakeField) shakeToken(fieldRef.current, reduced);

    if (!reduced) {
      const { dx, dy } = rootOffset();
      const flights: Ghost[] = p.flights.flatMap((f) => {
        const twin = after.chips.get(f.twin);
        if (!twin) return [];
        let box: TokenBox;
        if ("after" in f.from) {
          // Where it would have landed: after the chip before it, or at the start of the next line if it doesn't fit.
          const prev = f.from.after
            ? after.chips.get(f.from.after)?.box
            : undefined;
          let x = prev ? prev.x + prev.w + GAP : PAD;
          let y = prev ? prev.y : PAD;
          if (x + f.from.w > list.clientWidth - PAD) {
            x = PAD;
            y += CHIP_H + PAD;
          }
          box = { x: x + dx, y: y + dy, w: f.from.w, h: CHIP_H };
        } else box = f.from;
        return [
          {
            key: ++ghostKey.current,
            kind: f.kind,
            text: f.text,
            box,
            to: shift(f.kind === "carry" ? twin.label : twin.box, dx, dy),
            twin: f.twin,
            delay: f.delay,
            appear: "after" in f.from,
          },
        ];
      });
      if (p.ghosts.length || flights.length)
        setGhosts((g) => [...g, ...p.ghosts, ...flights]);

      const input = inputRef.current;
      if (p.inputFrom && input) {
        const i = input.getBoundingClientRect();
        const root = rootRef.current!.getBoundingClientRect();
        const from = p.inputFrom.box;
        input.parentElement!.animate(
          [
            {
              transform: `translate(${from.x - (i.left - root.left)}px, ${from.y + from.h / 2 - (i.top - root.top + i.height / 2)}px)`,
            },
            { transform: "none" },
          ],
          { duration: 440, easing: EASE },
        );
        if (p.inputFrom.fade)
          input.animate(
            [
              { opacity: 0, filter: "blur(4px)" },
              { opacity: 1, filter: "blur(0px)" },
            ],
            { duration: 360, delay: 80, easing: EASE, fill: "backwards" },
          );
      }
    }

    const input = inputRef.current;
    if (p.focus === "input" && input) {
      quietFocus.current = document.activeElement !== input;
      input.focus({ preventScroll: true });
      const end = input.value.length;
      input.setSelectionRange(end, end);
    } else if (p.focus) chip(p.focus)?.focus({ preventScroll: true });
    // Widths settle here (after TextMorph), so the folded count is measured again too.
    measure();
  }, [playTick]);

  const ghostDone = React.useCallback(
    (ghost: Ghost) => {
      setGhosts((g) => g.filter((x) => x.key !== ghost.key));
      if (ghost.kind === "fly" && ghost.twin)
        pulseToken(
          listRef.current?.querySelector<HTMLElement>(
            `[data-token="${CSS.escape(ghost.twin)}"]`,
          ),
          reduced,
        );
    },
    [reduced],
  );

  React.useLayoutEffect(() => {
    measure();
  }, [measure, collapsed, tags, resolving]);

  React.useEffect(() => {
    const list = listRef.current;
    if (!list) return;
    const observer = new ResizeObserver(() => measure());
    observer.observe(list);
    return () => observer.disconnect();
  }, [measure]);

  // ── Suggestions ────────────────────────────────────────
  React.useEffect(() => {
    if (typeof suggestions !== "function" || !inputFocus) return;
    let live = true;
    const q = text.trim();
    Promise.resolve(suggestions(q)).then((found) => {
      if (live) {
        const taken = new Set(tags.map((t) => t.value));
        const keep = (res: TagInputSuggestion[]) =>
          res.filter((s) => !taken.has(normalize(s.value))).slice(0, 6);
        setAsyncOptions(keep(found));
      }
    });
    return () => {
      live = false;
    };
  }, [text, tags, suggestions, inputFocus, normalize]);

  const options = React.useMemo(() => {
    if (!suggestions || !inputFocus) return [];
    if (typeof suggestions === "function") return asyncOptions;
    const q = text.trim().toLowerCase();
    const taken = new Set(tags.map((t) => t.value));
    const keep = (found: TagInputSuggestion[]) =>
      found.filter((s) => !taken.has(normalize(s.value))).slice(0, 6);
    return keep(
      q
        ? suggestions.filter((s) =>
            [s.value, s.label, s.description].some((f) =>
              f?.toLowerCase().includes(q),
            ),
          )
        : suggestions,
    );
  }, [suggestions, inputFocus, asyncOptions, text, tags, normalize]);

  const query = text.trim();
  const exact = options.some(
    (o) =>
      normalize(o.value) === normalize(query) ||
      o.label?.toLowerCase() === query.toLowerCase(),
  );
  const rows = React.useMemo<Row[]>(
    () => [
      ...options,
      ...(createLabel && query && !exact
        ? [{ value: query, label: createLabel(query), create: true }]
        : []),
    ],
    [options, createLabel, query, exact],
  );
  const open =
    !!suggestions && inputFocus && !dismissed && rows.length > 0 && !disabled;
  const activeRow = open ? Math.min(active, rows.length - 1) : -1;
  // While the list folds away it keeps the rows it had, rather than flashing what an empty query would match.
  const [keptRows, setKeptRows] = React.useState(rows);
  if (open && keptRows !== rows) {
    setKeptRows(rows);
  }
  const shownRows = open ? rows : keptRows;

  // The first match is ready for Enter while you type; nothing is while the field is empty.
  const [prevQueryKey, setPrevQueryKey] = React.useState(
    () => `${text}:${options.length}`,
  );
  const queryKey = `${text}:${options.length}`;
  if (queryKey !== prevQueryKey) {
    setPrevQueryKey(queryKey);
    setActive(text.trim() ? 0 : -1);
  }

  const pick = (row: Row, index: number) => {
    setDismissed(true);
    if (row.create) return commitText(row.value);
    const label = rowRefs.current[index]
      ?.querySelector("[data-option-label]")
      ?.getBoundingClientRect();
    const root = rootRef.current!.getBoundingClientRect();
    const from = label
      ? {
          x: label.left - root.left,
          y: label.top - root.top,
          w: label.width,
          h: label.height,
        }
      : { x: 0, y: 0, w: 1, h: 18 };
    setText("");
    add([{ value: row.value, label: row.label, image: row.image }], {
      pick: from,
    });
  };

  // The highlight glides between rows; its first placement doesn't.
  const [mark, setMark] = React.useState({
    y: 0,
    h: 0,
    on: false,
    slide: false,
  });
  React.useLayoutEffect(() => {
    const el = rowRefs.current[activeRow];
    setMark((m) => {
      if (!el) return m.on ? { ...m, on: false, slide: false } : m;
      const next = {
        y: el.offsetTop,
        h: el.offsetHeight,
        on: true,
        slide: m.on,
      };
      return m.y === next.y &&
        m.h === next.h &&
        m.on === next.on &&
        m.slide === next.slide
        ? m
        : next;
    });
  }, [activeRow, rows.length, open]);
  React.useEffect(() => {
    if (activeRow >= 0)
      rowRefs.current[activeRow]?.scrollIntoView({ block: "nearest" });
  }, [activeRow]);

  // ── Keys ───────────────────────────────────────────────
  const ids = tags.map((t) => t.id);
  const focusChip = (id: string | undefined) => {
    if (!id) return inputRef.current?.focus();
    listRef.current
      ?.querySelector<HTMLElement>(`[data-token="${CSS.escape(id)}"]`)
      ?.focus();
  };

  const onInputKey = (e: React.KeyboardEvent<HTMLInputElement>) => {
    const input = e.currentTarget;
    if (open && (e.key === "ArrowDown" || e.key === "ArrowUp")) {
      e.preventDefault();
      const n = rows.length;
      setActive((a) =>
        e.key === "ArrowDown" ? (a + 1) % n : a <= 0 ? n - 1 : a - 1,
      );
    } else if (e.key === "ArrowDown" && suggestions && dismissed) {
      e.preventDefault();
      setDismissed(false);
    } else if (e.key === "Enter") {
      if (open && activeRow >= 0) {
        e.preventDefault();
        pick(rows[activeRow], activeRow);
      } else if (text.trim()) {
        e.preventDefault();
        commitText();
      }
    } else if (e.key === "Tab" && !e.shiftKey && text.trim()) {
      commitText();
    } else if (e.key === "Escape" && open) {
      e.preventDefault();
      setDismissed(true);
    } else if (
      (e.key === "Backspace" || e.key === "ArrowLeft") &&
      input.selectionStart === 0 &&
      input.selectionEnd === 0 &&
      ids.length
    ) {
      e.preventDefault();
      focusChip(ids[ids.length - 1]);
    }
  };

  const onChipKey = (e: React.KeyboardEvent<HTMLElement>, id: string) => {
    const i = ids.indexOf(id);
    const keys: Record<string, () => void> = {
      ArrowLeft: () => focusChip(ids[Math.max(0, i - 1)]),
      ArrowRight: () => focusChip(ids[i + 1]),
      Home: () => focusChip(ids[0]),
      End: () => focusChip(undefined),
      Escape: () => focusChip(undefined),
      Backspace: () => edit(id),
      Enter: () => edit(id),
      Delete: () => remove(id, ids[i + 1] ?? "input"),
    };
    const run = keys[e.key];
    if (!run) return;
    e.preventDefault();
    run();
  };

  const onType = (next: string) => {
    if (!separators.test(next)) {
      setDismissed(false);
      return setText(next);
    }
    const words = next.split(separators);
    const rest = words.pop() ?? "";
    const done = words.filter((w) => w.trim());
    if (done.length === 1) {
      const lead = next.length - next.trimStart().length;
      const box = textBox(lead, done[0].trim());
      setText(rest);
      add([{ value: done[0] }], { type: box });
    } else if (done.length > 1) {
      const point = caretPoint();
      setText(rest);
      add(
        done.map((w) => ({ value: w })),
        { paste: point },
      );
    } else setText(rest);
  };

  // ── Render ─────────────────────────────────────────────
  const invalid = tags.find((t) => t.error);
  const line =
    notice ??
    (invalid
      ? { text: invalid.error!, tone: "error" as const }
      : hint
        ? { text: hint, tone: "muted" as const }
        : null);
  const lineId = `${uid}-line`;
  const listId = `${uid}-options`;
  const hidden = new Set(cut?.hidden ?? []);
  const tone =
    line?.tone === "error"
      ? "text-red-600 dark:text-red-400"
      : line?.tone === "warn"
        ? "text-amber-700 dark:text-amber-400"
        : "text-muted-foreground";

  return (
    <div
      ref={rootRef}
      className={`relative w-full text-foreground ${className}`}
      onFocus={() => setWithin(true)}
      onBlur={(e) => {
        const root = e.currentTarget;
        // A chip that's removed while focused takes focus with it for a moment; look again once things settle.
        requestAnimationFrame(() => {
          if (root.contains(document.activeElement)) return;
          setWithin(false);
          setSelected(null);
        });
      }}
      {...props}
    >
      <span
        ref={mirrorRef}
        aria-hidden="true"
        className="pointer-events-none invisible absolute left-0 top-0 whitespace-pre text-[14px] [@media(pointer:coarse)]:text-[16px]"
      />

      <div className="relative">
        <div
          ref={fieldRef}
          onMouseDown={(e) => {
            if (
              disabled ||
              (e.target as HTMLElement).closest("[data-token], button, input")
            )
              return;
            e.preventDefault();
            inputRef.current?.focus();
          }}
          className={`cursor-text rounded-[19px] border bg-background transition-[border-color,opacity] duration-200 ${disabled ? "cursor-default opacity-60" : ""}`}
          style={{
            borderColor: inputFocus
              ? "color-mix(in oklab, var(--ring) 55%, var(--border))"
              : "var(--border)",
          }}
        >
          {/* clip, not hidden: a hidden box can still be scrolled, and focusing the input would scroll the chips away. */}
          <div ref={wrapRef} className="overflow-clip">
            <div
              ref={listRef}
              className="relative flex flex-wrap items-center gap-x-1.5"
              style={{ padding: PAD, rowGap: PAD }}
            >
              <div role="list" aria-label={label} className="contents">
                {tags.map((t, i) => {
                  const busy = resolving.has(t.id);
                  const shown = display(t);
                  const named = !!t.label && t.label !== t.value;
                  const slot = busy || !!t.error || !!t.image || named;
                  const gone = hidden.has(t.id);
                  return (
                    <span
                      key={t.id}
                      data-token={t.id}
                      role="listitem"
                      tabIndex={-1}
                      aria-label={`${shown}${named ? `, ${t.value}` : ""}${t.error ? `, ${t.error}` : ""}${busy ? ", looking up" : ""}`}
                      aria-describedby={`${uid}-keys`}
                      title={shown.length > LONG ? shown : undefined}
                      onFocus={() => setSelected(t.id)}
                      onBlur={() => setSelected((s) => (s === t.id ? null : s))}
                      onKeyDown={(e) => onChipKey(e, t.id)}
                      onMouseDown={() => {
                        wasSelected.current = selected === t.id;
                      }}
                      onClick={(e) => {
                        if (
                          wasSelected.current &&
                          !(e.target as HTMLElement).closest("button")
                        )
                          edit(t.id);
                      }}
                      className={`relative inline-flex h-7 max-w-full shrink-0 cursor-default select-none items-center rounded-full text-[13px] outline-none will-change-transform ${
                        t.error
                          ? "text-red-600 dark:text-red-400"
                          : "text-foreground"
                      }`}
                      style={{
                        opacity: gone ? 0 : 1,
                        filter: gone ? "blur(3px)" : "none",
                        pointerEvents: gone ? "none" : undefined,
                        transition: reduced
                          ? "none"
                          : `opacity 260ms ${EASE} ${gone ? 0 : Math.min(i * 18, 180)}ms, filter 260ms ${EASE}`,
                      }}
                    >
                      <span
                        data-token-shell=""
                        aria-hidden="true"
                        className="absolute inset-y-0 left-0 w-full rounded-full transition-[background-color,box-shadow] duration-200"
                        style={shellStyle(!!t.error, selected === t.id)}
                      />
                      <span
                        data-token-extra=""
                        aria-hidden="true"
                        className="relative flex h-5 shrink-0 items-center justify-center"
                        style={{
                          width: slot ? 20 : 0,
                          marginLeft: slot ? 4 : 0,
                        }}
                      >
                        <span
                          className="absolute inset-0 flex items-center justify-center"
                          style={swap(busy, reduced)}
                        >
                          <span
                            className={`size-3 rounded-full border-[1.5px] border-current border-t-transparent text-muted-foreground motion-reduce:animate-none ${busy ? "animate-spin" : ""}`}
                          />
                        </span>
                        <span
                          className="absolute inset-0 flex items-center justify-center"
                          style={swap(!busy && !!t.error, reduced)}
                        >
                          <svg
                            viewBox="0 0 16 16"
                            className="size-3.5"
                            fill="none"
                          >
                            <circle
                              cx="8"
                              cy="8"
                              r="6.25"
                              stroke="currentColor"
                              strokeWidth="1.5"
                            />
                            <path
                              d="M8 4.75v3.75"
                              stroke="currentColor"
                              strokeWidth="1.75"
                              strokeLinecap="round"
                            />
                            <circle cx="8" cy="11" r="1" fill="currentColor" />
                          </svg>
                        </span>
                        <span
                          className="absolute inset-0 flex items-center justify-center"
                          style={swap(
                            !busy && !t.error && (!!t.image || named),
                            reduced,
                          )}
                        >
                          {(t.image || named) && (
                            <Avatar image={t.image} name={shown} size={20} />
                          )}
                        </span>
                      </span>
                      {/* Only a long label clips (inside its own box, which is what glides): a short one never cuts the letters
                          of the address it's morphing from. */}
                      <span
                        data-token-label=""
                        className={`relative whitespace-nowrap py-1 ${shown.length > LONG ? "min-w-0 max-w-[11rem] overflow-hidden" : ""}`}
                        style={{ marginLeft: slot ? 6 : 10, marginRight: 2 }}
                      >
                        <TextMorph animateWidth={false} aria-hidden="true">
                          {shown}
                        </TextMorph>
                      </span>
                      <button
                        type="button"
                        data-token-extra=""
                        tabIndex={-1}
                        aria-label={`Remove ${shown}`}
                        disabled={disabled}
                        onMouseDown={(e) => e.preventDefault()}
                        onClick={() =>
                          remove(
                            t.id,
                            rootRef.current?.contains(document.activeElement)
                              ? "input"
                              : undefined,
                          )
                        }
                        className="relative mr-1 flex size-5 shrink-0 cursor-pointer items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:cursor-default"
                      >
                        <Cross />
                      </button>
                    </span>
                  );
                })}
              </div>

              <span
                data-token-input=""
                className="flex h-7 items-center pl-1.5"
                style={{
                  flex: collapsed ? "0 0 0px" : "1 1 7rem",
                  minWidth: collapsed ? 0 : "7rem",
                }}
              >
                <input
                  ref={inputRef}
                  value={text}
                  disabled={disabled}
                  placeholder={tags.length ? undefined : placeholder}
                  role="combobox"
                  aria-label={label}
                  aria-expanded={open}
                  aria-controls={open ? listId : undefined}
                  aria-activedescendant={
                    activeRow >= 0 ? `${uid}-opt-${activeRow}` : undefined
                  }
                  aria-autocomplete={suggestions ? "list" : undefined}
                  aria-describedby={line ? lineId : undefined}
                  autoComplete="off"
                  spellCheck={false}
                  onFocus={() => {
                    setInputFocus(true);
                    if (!quietFocus.current) setDismissed(false);
                    quietFocus.current = false;
                  }}
                  onBlur={(e) => {
                    setInputFocus(false);
                    if (
                      !rootRef.current?.contains(
                        e.relatedTarget as Node | null,
                      ) &&
                      text.trim()
                    )
                      commitText();
                  }}
                  onChange={(e) => onType(e.target.value)}
                  onPaste={(e) => {
                    const pasted = e.clipboardData.getData("text");
                    if (!separators.test(pasted)) return;
                    e.preventDefault();
                    pasteText(
                      pasted,
                      e.currentTarget.selectionStart ?? text.length,
                      e.currentTarget.selectionEnd ?? text.length,
                    );
                  }}
                  onKeyDown={onInputKey}
                  className="h-7 w-full min-w-0 bg-transparent text-[14px] outline-none placeholder:text-muted-foreground disabled:cursor-default [@media(pointer:coarse)]:text-[16px]"
                />
              </span>

              {/* What folded away, counted at the end of the last line that shows. */}
              <span
                ref={pillRef}
                aria-hidden="true"
                onMouseDown={(e) => {
                  e.preventDefault();
                  inputRef.current?.focus();
                }}
                className="absolute left-0 top-0 inline-flex h-7 cursor-pointer items-center rounded-full px-2.5 text-[12.5px] tabular-nums text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]"
                style={{
                  transform: `translate(${cut?.x ?? PAD}px, ${cut?.y ?? PAD}px)`,
                  opacity: cut ? 1 : 0,
                  filter: cut ? "none" : "blur(3px)",
                  pointerEvents: cut ? undefined : "none",
                  transition: reduced
                    ? "none"
                    : `opacity 260ms ${EASE} ${cut ? 120 : 0}ms, filter 260ms ${EASE}`,
                }}
              >
                +<NumberRoll value={cut?.hidden.length ?? 0} duration={600} />
              </span>
            </div>
          </div>
        </div>

        {/* Suggestions open clear of the field and unfold from its edge. */}
        <div
          className="absolute inset-x-0 top-full z-20 pt-1.5"
          style={{
            clipPath: open
              ? "inset(0px -2px -2px -2px)"
              : "inset(0px -2px 100% -2px)",
            opacity: open ? 1 : 0,
            visibility: open ? "visible" : "hidden",
            transition: reduced
              ? "none"
              : `clip-path 340ms ${EASE}, opacity 200ms ${EASE}, visibility 0s linear ${open ? "0s" : "340ms"}`,
          }}
        >
          <div
            role="listbox"
            id={listId}
            aria-label={`${label}: suggestions`}
            onMouseDown={(e) => e.preventDefault()}
            className="relative max-h-64 overflow-auto rounded-[14px] border border-border bg-popover p-1 text-popover-foreground"
          >
            <span
              aria-hidden="true"
              className="absolute inset-x-1 top-0 rounded-[10px] bg-accent"
              style={{
                transform: `translateY(${mark.y}px)`,
                height: mark.h,
                opacity: mark.on ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `${mark.slide ? `transform 260ms ${EASE}, height 260ms ${EASE}, ` : ""}opacity 160ms ${EASE}`,
              }}
            />
            {shownRows.map((row, i) => (
              <div
                key={`${row.create ? "create" : "row"}-${row.value}`}
                id={`${uid}-opt-${i}`}
                ref={(el) => {
                  rowRefs.current[i] = el;
                }}
                role="option"
                aria-selected={i === activeRow}
                onMouseMove={() => i !== activeRow && setActive(i)}
                onClick={() => pick(row, i)}
                className="relative flex min-h-10 cursor-pointer items-center gap-2.5 rounded-[10px] px-2 py-1.5"
              >
                {row.create ? (
                  <span className="flex size-6 shrink-0 items-center justify-center rounded-full text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]">
                    <svg
                      viewBox="0 0 12 12"
                      className="size-3"
                      fill="none"
                      aria-hidden="true"
                    >
                      <path
                        d="M6 2.5v7M2.5 6h7"
                        stroke="currentColor"
                        strokeWidth="1.4"
                        strokeLinecap="round"
                      />
                    </svg>
                  </span>
                ) : (
                  (row.image || row.label) && (
                    <Avatar image={row.image} name={display(row)} size={24} />
                  )
                )}
                <span className="flex min-w-0 flex-col">
                  <span className="truncate text-[13.5px] leading-tight">
                    <span data-option-label="">{display(row)}</span>
                  </span>
                  {!row.create &&
                    (row.description ||
                      (row.label && row.label !== row.value)) && (
                      <span className="truncate text-[12px] leading-tight text-muted-foreground">
                        {row.description ?? row.value}
                      </span>
                    )}
                </span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Hint, error or notice: one line that morphs, and folds away when there's nothing to say. */}
      <div
        className="grid transition-[grid-template-rows] duration-300"
        style={{
          gridTemplateRows: line ? "1fr" : "0fr",
          transitionTimingFunction: EASE,
        }}
      >
        <div className="min-w-0 overflow-hidden">
          <p
            id={lineId}
            className={`pl-1 pt-2 text-[12.5px] transition-colors duration-300 ${tone}`}
          >
            <Line text={line?.text ?? ""} reduced={reduced} />
          </p>
        </div>
      </div>

      {/* Ghosts: chips that leave, fly into a twin, drop their shell, or carry a name in. */}
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 z-30"
      >
        {ghosts.map((g) => (
          <GhostChip key={g.key} ghost={g} onDone={ghostDone} />
        ))}
      </div>

      {name && (
        <input
          type="hidden"
          name={name}
          value={tags
            .filter((t) => !t.error)
            .map((t) => t.value)
            .join(",")}
        />
      )}
      <p id={`${uid}-keys`} className="sr-only">
        Backspace edits, Delete removes, arrow keys move between tags.
      </p>
      <p className="sr-only" role="status" aria-live="polite">
        {announce}
      </p>
    </div>
  );
}

/* ─────────────────────────────────────────────────────────
 * TOKEN FLIP: chips that keep their place on screen
 *
 *   snapshot  where every chip, its label and the input sit in
 *             the layout, plus where they are on screen right
 *             now; taken at the keystroke, the paste or the
 *             click, never at the last render
 *   play      after React lays the new order out, every chip
 *             glides from its old place to its new one. Glides
 *             are additive: a change that lands mid-glide (a name
 *             resolving while a paste is still landing) adds its
 *             own offset on top, so nothing restarts or jumps.
 *             A chip that changed width eases its shell; a new
 *             chip grows its shell round the letters you typed,
 *             or spills out of the caret when pasted.
 *   ghosts    copies that leave, or fly into a twin, live in an
 *             overlay so the real list never waits for them
 *
 * Transforms, a shell's width and a one-off clip only; nothing
 * here runs per pointer move. Elements are found by data
 * attributes: data-token, data-token-shell, data-token-label,
 * data-token-extra and data-token-input.
 * ───────────────────────────────────────────────────────── */

export type TokenBox = { x: number; y: number; w: number; h: number };
export type TokenChip = {
  /** Layout boxes in list coordinates, transforms ignored. */
  box: TokenBox;
  label: TokenBox;
  /** The shell's width as drawn right now (mid-ease included). */
  shell: number;
  /** Where the chip and its label are on screen right now, in list coordinates. */
  screen: TokenBox;
  screenLabel: TokenBox;
};
export type TokenSnapshot = {
  chips: Map<string, TokenChip>;
  input: TokenBox | null;
};

/**
 * How a new chip arrives. "text": its letters stay where they were typed (box) or where they are (no box) while the
 * shell grows round them; `hold` keeps them hidden while a copy is carried in. "point": it spills out of a point (paste).
 */
export type TokenEnter =
  | { from: "text"; box?: TokenBox; delay?: number; hold?: number }
  | { from: "point"; x: number; y: number; delay: number };

export const TOKEN_EASE = "cubic-bezier(0.16,1,0.3,1)";
export const TOKEN_THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const GLIDE = 440;
const SPILL = 560;
const ENTER = "token-enter";

const chipsOf = (list: HTMLElement) =>
  list.querySelectorAll<HTMLElement>("[data-token]");
const part = (chip: HTMLElement, name: string) =>
  chip.querySelector<HTMLElement>(`[data-token-${name}]`);

const screenBox = (el: Element, origin: DOMRect): TokenBox => {
  const r = el.getBoundingClientRect();
  return {
    x: r.left - origin.left,
    y: r.top - origin.top,
    w: r.width,
    h: r.height,
  };
};

/** The layout box (offsets, so running transforms don't count) in list coordinates. */
function layoutBox(
  el: HTMLElement,
  list: HTMLElement,
  origin: DOMRect,
): TokenBox {
  let x = 0;
  let y = 0;
  let node: HTMLElement | null = el;
  while (node && node !== list) {
    x += node.offsetLeft;
    y += node.offsetTop;
    node = node.offsetParent as HTMLElement | null;
  }
  return node === list
    ? { x, y, w: el.offsetWidth, h: el.offsetHeight }
    : screenBox(el, origin);
}

export function snapshotTokens(list: HTMLElement): TokenSnapshot {
  const origin = list.getBoundingClientRect();
  const chips = new Map<string, TokenChip>();
  chipsOf(list).forEach((chip) => {
    const label = part(chip, "label") ?? chip;
    const shell = part(chip, "shell");
    chips.set(chip.dataset.token!, {
      box: layoutBox(chip, list, origin),
      label: layoutBox(label, list, origin),
      shell: shell
        ? parseFloat(getComputedStyle(shell).width) || chip.offsetWidth
        : chip.offsetWidth,
      screen: screenBox(chip, origin),
      screenLabel: screenBox(label, origin),
    });
  });
  const input = list.querySelector<HTMLElement>("[data-token-input]");
  return { chips, input: input ? layoutBox(input, list, origin) : null };
}

const moved = (dx: number, dy: number) =>
  Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5;

/** An offset that decays to nothing, added on top of whatever else is moving the element. */
function glide(el: HTMLElement, dx: number, dy: number) {
  el.animate(
    [
      { transform: `translate(${dx}px, ${dy}px)` },
      { transform: "translate(0px, 0px)" },
    ],
    { duration: GLIDE, easing: TOKEN_EASE, composite: "add" },
  );
}

const stopMoving = (el: HTMLElement) =>
  el
    .getAnimations()
    .forEach(
      (a) =>
        (a.effect as KeyframeEffect | null)
          ?.getKeyframes()
          .some((k) => "transform" in k) && a.cancel(),
    );

/** A pasted chip spills out of a point (list coordinates) after `delay`, and remembers it in case the layout moves first. */
function spill(
  chip: HTMLElement,
  x: number,
  y: number,
  at: TokenBox,
  delay: number,
) {
  chip.dataset.tokenFromX = String(x);
  chip.dataset.tokenFromY = String(y);
  const a = chip.animate(
    [
      {
        transform: `translate(${x - at.x}px, ${y - at.y}px) scale(0.86)`,
        opacity: 0,
        filter: "blur(4px)",
      },
      { transform: "none", opacity: 1, filter: "blur(0px)" },
    ],
    { duration: SPILL, delay, easing: TOKEN_EASE, fill: "backwards" },
  );
  a.id = ENTER;
}

/**
 * The layout moved while a chip was still spilling in. Stacking a glide on top would drift it (its own offset waits out
 * the delay while the glide decays), so aim it again: from its point if it hasn't left, or on from where it is now.
 */
function reaim(
  chip: HTMLElement,
  entry: Animation,
  was: TokenChip,
  now: TokenBox,
) {
  const delay = Number(entry.effect?.getTiming().delay ?? 0);
  const t = Number(entry.currentTime ?? 0);
  if (t < delay) {
    stopMoving(chip);
    spill(
      chip,
      Number(chip.dataset.tokenFromX),
      Number(chip.dataset.tokenFromY),
      now,
      delay - t,
    );
    return;
  }
  const { opacity, filter } = getComputedStyle(chip);
  stopMoving(chip);
  const s = was.screen;
  const a = chip.animate(
    [
      {
        transform: `translate(${s.x + s.w / 2 - (now.x + now.w / 2)}px, ${s.y + s.h / 2 - (now.y + now.h / 2)}px) scale(${s.w / Math.max(1, now.w)})`,
        opacity,
        filter,
      },
      { transform: "none", opacity: 1, filter: "blur(0px)" },
    ],
    { duration: Math.max(160, SPILL + delay - t), easing: TOKEN_EASE },
  );
  a.id = ENTER;
}

/**
 * Glide everything from `before` to where it sits now. `enter` says how chips that weren't there arrive; `skipInput`
 * keeps the input still (when typed text has just become a chip, the caret is already in place). Returns the new layout.
 */
export function playTokens(
  list: HTMLElement,
  before: TokenSnapshot,
  options: {
    enter?: Map<string, TokenEnter>;
    skipInput?: boolean;
    reduced: boolean;
  },
): TokenSnapshot {
  const { enter, skipInput, reduced } = options;
  const after = snapshotTokens(list);
  if (reduced) return after;

  for (const chip of chipsOf(list)) {
    const id = chip.dataset.token!;
    const now = after.chips.get(id)!;
    const was = before.chips.get(id);
    const shell = part(chip, "shell");
    const label = part(chip, "label");

    if (was) {
      const entry = chip
        .getAnimations()
        .find((a) => a.id === ENTER && a.playState === "running");
      if (moved(was.box.x - now.box.x, was.box.y - now.box.y)) {
        if (entry) reaim(chip, entry, was, now.box);
        else glide(chip, was.box.x - now.box.x, was.box.y - now.box.y);
      }
      // Its width changed (a name arrived, an avatar opened): the shell eases from the width it's drawn at.
      if (shell && Math.abs(was.shell - now.box.w) > 0.5) {
        shell
          .getAnimations()
          .forEach(
            (a) =>
              (a.effect as KeyframeEffect | null)
                ?.getKeyframes()
                .some((k) => "width" in k) && a.cancel(),
          );
        shell.animate(
          [{ width: `${was.shell}px` }, { width: `${now.box.w}px` }],
          { duration: GLIDE, easing: TOKEN_EASE },
        );
      }
      const ldx = was.label.x - was.box.x - (now.label.x - now.box.x);
      if (label && Math.abs(ldx) > 0.5) glide(label, ldx, 0);
      continue;
    }

    const how = enter?.get(id);
    if (!how) continue;
    if (how.from === "text") {
      // The letters stay where they were; the shell grows round them from their own outline.
      const L = now.label;
      const C = now.box;
      const delay = how.delay ?? 0;
      if (label && how.box) {
        label.style.transformOrigin = "left center";
        label.animate(
          [
            {
              transform: `translate(${how.box.x - L.x}px, ${how.box.y + how.box.h / 2 - (L.y + L.h / 2)}px) scale(${how.box.w / Math.max(1, L.w)})`,
            },
            { transform: "none" },
          ],
          { duration: GLIDE, delay, easing: TOKEN_EASE, fill: "backwards" },
        );
      }
      if (label && how.hold)
        label.animate([{ opacity: 0 }, { opacity: 0 }], { duration: how.hold });
      const left = Math.max(0, L.x - C.x - 3);
      const right = Math.max(0, C.x + C.w - (L.x + L.w) - 3);
      shell?.animate(
        [
          {
            clipPath: `inset(4px ${right}px 4px ${left}px round 999px)`,
            opacity: 0,
          },
          { clipPath: `inset(0px 0px 0px 0px round 999px)`, opacity: 1 },
        ],
        { duration: 480, delay, easing: TOKEN_EASE, fill: "backwards" },
      );
      chip.querySelectorAll<HTMLElement>("[data-token-extra]").forEach((el) =>
        el.animate(
          [
            { opacity: 0, transform: "scale(0.6)", filter: "blur(3px)" },
            { opacity: 1, transform: "none", filter: "blur(0px)" },
          ],
          {
            duration: 340,
            delay: delay + 140,
            easing: TOKEN_EASE,
            fill: "backwards",
          },
        ),
      );
    } else {
      // Pasted: the chip spills out of the caret and lands in its place.
      spill(chip, how.x, how.y, now.box, how.delay);
    }
  }

  const input = list.querySelector<HTMLElement>("[data-token-input]");
  if (
    input &&
    before.input &&
    after.input &&
    !skipInput &&
    moved(before.input.x - after.input.x, before.input.y - after.input.y)
  )
    glide(
      input,
      before.input.x - after.input.x,
      before.input.y - after.input.y,
    );
  return after;
}

/** A chip that's already here takes a little bump and its ring flashes: "this one". */
export function pulseToken(
  chip: HTMLElement | null | undefined,
  reduced: boolean,
) {
  if (!chip || reduced) return;
  chip.animate(
    [
      { transform: "scale(1)" },
      { transform: "scale(1.08)" },
      { transform: "scale(1)" },
    ],
    { duration: 420, easing: TOKEN_THROW, composite: "add" },
  );
  part(chip, "shell")?.animate(
    [
      { boxShadow: "inset 0 0 0 1px var(--ring)" },
      { boxShadow: "inset 0 0 0 1px var(--ring)", offset: 0.4 },
      { boxShadow: "inset 0 0 0 1px var(--border)" },
    ],
    { duration: 900, easing: TOKEN_EASE },
  );
}

/** The no: a short shake. */
export function shakeToken(
  el: HTMLElement | null | undefined,
  reduced: boolean,
  delay = 0,
) {
  if (!el || reduced) return;
  el.animate(
    [
      { transform: "translateX(0)" },
      { transform: "translateX(-4px)" },
      { transform: "translateX(4px)" },
      { transform: "translateX(-2px)" },
      { transform: "translateX(0)" },
    ],
    { duration: 380, delay, easing: "ease-out", composite: "add" },
  );
}

/** Keyframes for a ghost leaving where it stood. */
export const LEAVE_FRAMES: Keyframe[] = [
  { opacity: 1, transform: "none", filter: "blur(0px)" },
  { opacity: 0, transform: "scale(0.86)", filter: "blur(4px)" },
];

/** Keyframes for letters carried from one box onto another (same text), landing exactly. */
export function carryFrames(from: TokenBox, to: TokenBox): Keyframe[] {
  const scale = to.w / Math.max(1, from.w);
  return [
    { transform: "none" },
    {
      transform: `translate(${to.x - from.x}px, ${to.y + to.h / 2 - (from.y + from.h / 2)}px) scale(${Math.min(1.2, Math.max(0.8, scale))})`,
    },
  ];
}

/** Keyframes for a ghost flying from one box into another and dissolving as it arrives; `appear` fades it in first. */
export function flyFrames(
  from: TokenBox,
  to: TokenBox,
  appear = false,
): Keyframe[] {
  // Centre onto centre at its own size: letters that grew or shrank in flight would read as a different chip.
  const dx = to.x + to.w / 2 - (from.x + from.w / 2);
  const dy = to.y + to.h / 2 - (from.y + from.h / 2);
  return [
    ...(appear
      ? [
          { transform: "scale(0.86)", opacity: 0, filter: "blur(4px)" },
          { transform: "none", opacity: 1, filter: "blur(0px)", offset: 0.24 },
        ]
      : [{ transform: "none", opacity: 1, filter: "blur(0px)" }]),
    {
      transform: `translate(${dx * 0.7}px, ${dy * 0.7}px)`,
      opacity: 0.85,
      filter: "blur(0px)",
      offset: appear ? 0.62 : 0.5,
    },
    {
      transform: `translate(${dx}px, ${dy}px) scale(0.92)`,
      opacity: 0,
      filter: "blur(3px)",
    },
  ];
}

"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * ROLE MENU: a role pill that grows into the list of roles
 *
 *   open      the pill's own surface grows from its right edge
 *             into the panel (size and radius ease) while its
 *             label fades into the list; it opens upward when
 *             there's no room below
 *   pick      the panel folds back into the pill and the label
 *             morphs to the new role; while it saves, the
 *             chevron gives way to a small spinner
 *   refuse    if saving fails the label morphs back and the
 *             pill gives a short shake
 * ───────────────────────────────────────────────────────── */

export interface TeamRole {
  value: string;
  label: string;
  /** One line under the role in the menu: what it can do. */
  description?: string;
}

export interface RoleMenuProps {
  roles: TeamRole[];
  value: string;
  onValueChange: (role: string) => void;
  /** Shows a spinner in place of the chevron. */
  saving?: boolean;
  /** Bumped by the parent to shake the pill (a save failed). */
  shake?: number;
  /** Accessible name, e.g. "Role for Maya Chen". */
  label: string;
  /** Said before the role inside the pill, e.g. "as". */
  prefix?: string;
  disabled?: boolean;
  className?: string;
}

type Phase = "closed" | "opening" | "open" | "closing";

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const DURATION = 420;
const PANEL = 248;
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Chevron({ up, reduced }: { up: boolean; reduced: boolean }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className="size-3"
      style={{
        transform: up ? "rotate(180deg)" : "none",
        transition: reduced ? "none" : `transform 320ms ${EASE}`,
      }}
    >
      <path
        d="M4.5 6.25 8 9.75l3.5-3.5"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

/** The pill's insides, shared by the real pill and the copy that fades out as the surface grows. */
function PillFace({
  prefix,
  label,
  saving,
  up,
  reduced,
}: {
  prefix?: string;
  label: string;
  saving: boolean;
  up: boolean;
  reduced: boolean;
}) {
  return (
    <>
      {prefix && <span className="text-muted-foreground">{prefix}&nbsp;</span>}
      <TextMorph>{label}</TextMorph>
      <span className="relative ml-1 grid size-3 place-items-center text-muted-foreground">
        <span
          className="absolute inset-0 grid place-items-center"
          style={{
            opacity: saving ? 0 : 1,
            transform: saving ? "scale(0.6)" : "none",
            transition: reduced
              ? "none"
              : `opacity 200ms ${EASE}, transform 320ms ${EASE}`,
          }}
        >
          <Chevron up={up} reduced={reduced} />
        </span>
        <span
          className={`absolute inset-0.5 rounded-full border-[1.5px] border-current border-t-transparent motion-reduce:animate-none ${saving ? "animate-spin" : ""}`}
          style={{
            opacity: saving ? 1 : 0,
            transition: reduced ? "none" : `opacity 200ms ${EASE}`,
          }}
        />
      </span>
    </>
  );
}

export function RoleMenu({
  roles,
  value,
  onValueChange,
  saving = false,
  shake = 0,
  label,
  prefix,
  disabled = false,
  className = "",
}: RoleMenuProps) {
  const id = React.useId();
  const reduced = useReducedMotion();
  const [phase, setPhase] = React.useState<Phase>("closed");
  const [active, setActive] = React.useState(0);
  const [pill, setPill] = React.useState({ width: 0, height: 28 });
  const [panelHeight, setPanelHeight] = React.useState(0);
  const [fit, setFit] = React.useState({ up: false, width: PANEL, shift: 0 });
  const [highlight, setHighlight] = React.useState({
    top: 0,
    height: 0,
    ready: false,
  });
  const [quiet, setQuiet] = React.useState(false);
  const wrapRef = React.useRef<HTMLDivElement>(null);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const panelRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLDivElement>(null);
  const rowRefs = React.useRef<(HTMLDivElement | null)[]>([]);
  const timer = React.useRef(0);
  const selected = roles.find((r) => r.value === value);
  const expanded = phase === "open";
  const mounted = phase !== "closed";
  const [prevPhase, setPrevPhase] = React.useState(phase);
  if (phase !== prevPhase) {
    setPrevPhase(phase);
    if (phase === "closed") {
      setHighlight({ top: 0, height: 0, ready: false });
    }
  }

  const measureFit = () => {
    const wrap = wrapRef.current;
    if (!wrap) return;
    const rect = wrap.getBoundingClientRect();
    const viewport = document.documentElement.clientWidth;
    const width = Math.min(PANEL, viewport - 32);
    // Anchored at the pill's right edge; pushed right if that would leave the screen.
    const shift = Math.max(0, 16 - (rect.right - width));
    const estimate = roles.length * 52 + 12;
    const up =
      window.innerHeight - rect.top < estimate + 24 &&
      rect.bottom > estimate + 24;
    setFit((f) =>
      f.up === up && f.width === width && f.shift === shift
        ? f
        : { up, width, shift },
    );
  };

  const open = () => {
    if (disabled || saving || phase === "open" || phase === "opening") return;
    window.clearTimeout(timer.current);
    measureFit();
    setActive(
      Math.max(
        0,
        roles.findIndex((r) => r.value === value),
      ),
    );
    setPhase(reduced ? "open" : "opening");
  };

  const close = React.useCallback(
    (refocus = true) => {
      window.clearTimeout(timer.current);
      if (refocus) triggerRef.current?.focus({ preventScroll: true });
      if (reduced) return setPhase("closed");
      setPhase("closing");
      timer.current = window.setTimeout(() => setPhase("closed"), DURATION);
    },
    [reduced],
  );

  React.useEffect(() => {
    if (phase !== "opening") return;
    let inner = 0;
    const outer = requestAnimationFrame(
      () => (inner = requestAnimationFrame(() => setPhase("open"))),
    );
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [phase]);

  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  React.useLayoutEffect(() => {
    const trigger = triggerRef.current;
    if (!trigger) return;
    const measure = () =>
      setPill((p) =>
        p.width === trigger.offsetWidth && p.height === trigger.offsetHeight
          ? p
          : { width: trigger.offsetWidth, height: trigger.offsetHeight },
      );
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(trigger);
    return () => observer.disconnect();
  }, []);

  React.useLayoutEffect(() => {
    const panel = panelRef.current;
    if (!panel) return;
    setPanelHeight(panel.offsetHeight);
  }, [mounted, roles]);

  React.useLayoutEffect(() => {
    const row = rowRefs.current[active];
    if (!row) return;
    const top = row.offsetTop;
    const height = row.offsetHeight;
    setHighlight((h) =>
      h.top === top && h.height === height && h.ready === (h.ready || expanded)
        ? h
        : { top, height, ready: h.ready || expanded },
    );
  }, [active, expanded, mounted]);

  React.useEffect(() => {
    if (expanded) listRef.current?.focus({ preventScroll: true });
  }, [expanded]);

  React.useEffect(() => {
    if (!expanded) return;
    const onDown = (e: PointerEvent) => {
      if (!wrapRef.current?.contains(e.target as Node)) close(false);
    };
    document.addEventListener("pointerdown", onDown);
    return () => document.removeEventListener("pointerdown", onDown);
  }, [expanded, close]);

  // A failed save: the pill shakes where it stands.
  React.useEffect(() => {
    if (!shake || reduced) return;
    triggerRef.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [shake, reduced]);

  const choose = (role: TeamRole) => {
    close();
    if (role.value !== value) onValueChange(role.value);
  };

  const onListKey = (e: React.KeyboardEvent) => {
    const last = roles.length - 1;
    const move = (to: number) => {
      e.preventDefault();
      setActive(Math.max(0, Math.min(last, to)));
    };
    if (e.key === "ArrowDown") move(active === last ? 0 : active + 1);
    else if (e.key === "ArrowUp") move(active === 0 ? last : active - 1);
    else if (e.key === "Home") move(0);
    else if (e.key === "End") move(last);
    else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      if (roles[active]) choose(roles[active]);
    } else if (e.key === "Tab") close(false);
  };

  const width = expanded ? fit.width : pill.width;
  const height = expanded ? panelHeight : pill.height;
  const t = reduced
    ? "none"
    : `width ${DURATION}ms ${EASE}, height ${DURATION}ms ${EASE}, right ${DURATION}ms ${EASE}, border-radius ${DURATION}ms ${EASE}`;
  const listId = `${id}-roles`;
  const roleLabel = selected?.label ?? value;

  return (
    <div
      ref={wrapRef}
      className={`relative inline-flex shrink-0 ${className}`}
      onKeyDown={(e) => {
        setQuiet(false);
        if (e.key === "Escape" && expanded) {
          e.preventDefault();
          e.stopPropagation();
          close();
        }
      }}
      onBlur={(e) => {
        if (
          expanded &&
          document.hasFocus() &&
          !wrapRef.current?.contains(e.relatedTarget as Node)
        )
          close(false);
      }}
    >
      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="listbox"
        aria-expanded={expanded}
        aria-controls={mounted ? listId : undefined}
        aria-label={`${label}: ${roleLabel}`}
        aria-busy={saving || undefined}
        disabled={disabled}
        onClick={() => (expanded ? close() : open())}
        onPointerDown={() => setQuiet(true)}
        className={`inline-flex h-7 cursor-pointer items-center whitespace-nowrap rounded-full px-2.5 text-[12px] font-medium shadow-[inset_0_0_0_1px_var(--border)] transition-colors duration-150 hover:bg-accent disabled:cursor-default disabled:opacity-60 disabled:hover:bg-transparent aria-busy:cursor-default ${quiet ? "outline-none" : FOCUS}`}
      >
        <PillFace
          prefix={prefix}
          label={roleLabel}
          saving={saving}
          up={expanded}
          reduced={reduced}
        />
      </button>

      {mounted && (
        <div
          onPointerDown={(e) => {
            e.preventDefault();
            setQuiet(true);
          }}
          className="absolute z-30 overflow-hidden bg-popover text-popover-foreground"
          style={{
            [fit.up ? "bottom" : "top"]: 0,
            right: expanded ? -fit.shift : 0,
            width,
            height,
            borderRadius: expanded ? 16 : pill.height / 2,
            // The pill's own cavemio, the whole way: it is the same surface.
            boxShadow: "inset 0 0 0 1px var(--border)",
            transition: t,
          }}
        >
          {/* The pill's label, fading out as the surface grows and back in as it folds. */}
          <span
            aria-hidden="true"
            className={`pointer-events-none absolute right-0 inline-flex h-7 items-center whitespace-nowrap px-2.5 text-[12px] font-medium ${fit.up ? "bottom-0" : "top-0"}`}
            style={{
              opacity: expanded ? 0 : 1,
              transition: reduced
                ? "none"
                : `opacity ${expanded ? 120 : 260}ms ${EASE} ${expanded ? 0 : 120}ms`,
            }}
          >
            <PillFace
              prefix={prefix}
              label={roleLabel}
              saving={saving}
              up={expanded}
              reduced={reduced}
            />
          </span>
          <div
            ref={panelRef}
            className={`absolute right-0 p-1 ${fit.up ? "bottom-0" : "top-0"}`}
            style={{
              width: fit.width,
              opacity: expanded ? 1 : 0,
              transition: reduced
                ? "none"
                : `opacity ${expanded ? 260 : 120}ms ${EASE} ${expanded ? 90 : 0}ms`,
            }}
          >
            <div
              ref={listRef}
              id={listId}
              role="listbox"
              tabIndex={-1}
              aria-label={label}
              aria-activedescendant={`${id}-r${active}`}
              onKeyDown={onListKey}
              className="relative outline-none"
            >
              <span
                aria-hidden="true"
                className="pointer-events-none absolute inset-x-0 top-0 rounded-[12px] bg-accent"
                style={{
                  height: highlight.height,
                  transform: `translateY(${highlight.top}px)`,
                  opacity: highlight.ready ? 1 : 0,
                  transition:
                    highlight.ready && !reduced
                      ? `transform 300ms ${EASE}, height 300ms ${EASE}, opacity 200ms`
                      : "none",
                }}
              />
              {roles.map((r, i) => {
                const on = r.value === value;
                return (
                  <div
                    key={r.value}
                    ref={(el) => {
                      rowRefs.current[i] = el;
                    }}
                    id={`${id}-r${i}`}
                    role="option"
                    aria-selected={on}
                    onPointerMove={() => setActive(i)}
                    onClick={() => choose(r)}
                    className="relative flex cursor-pointer items-start gap-2 rounded-[12px] px-2.5 py-2"
                  >
                    <span className="min-w-0 flex-1">
                      <span className="block text-[12.5px] font-medium">
                        {r.label}
                      </span>
                      {r.description && (
                        <span className="mt-0.5 block text-[11.5px] leading-[1.4] text-muted-foreground">
                          {r.description}
                        </span>
                      )}
                    </span>
                    <svg
                      viewBox="0 0 16 16"
                      fill="none"
                      aria-hidden="true"
                      className="mt-0.5 size-3.5 shrink-0"
                    >
                      <path
                        d="M3.5 8.5 6.5 11.5 12.5 4.5"
                        stroke="currentColor"
                        strokeWidth="1.8"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        pathLength={1}
                        strokeDasharray={1}
                        style={{
                          strokeDashoffset: on && expanded ? 0 : 1,
                          transition: reduced
                            ? "none"
                            : `stroke-dashoffset 380ms ${EASE} 160ms`,
                        }}
                      />
                    </svg>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * ROW MOTION: rows that keep their place on screen
 *
 *   glide     after any render (a sort, a filter, new data from
 *             the server) every row that moved glides from its
 *             old place to its new one. Glides are additive, so
 *             a change that lands mid-glide adds its own offset
 *             instead of restarting anything
 *   travel    a row that sorts onto the page slides in from the
 *             side where it ranked before; one that sorts off
 *             slides out toward its new rank
 *   enter     a row that's new to the list fades in where it
 *             lands while the rows below glide clear of it
 *   leave     a row that's gone folds away where it stood. Its
 *             copy is the row's own element, detached by React
 *             and moved into a layer React never renders into,
 *             so a leaving row costs no render at all
 *   stagger   a sort can ask for the rows to set off one after
 *             another, top first
 *
 * Positions are layout offsets (transforms ignored), kept after
 * every render and whenever the list changes size (a row
 * opening its detail), so they're never stale. Rows are found
 * by data-row-id; ranks are their places in the whole sorted
 * list, not just the page.
 * ───────────────────────────────────────────────────────── */

type Seen = { top: number; height: number; el: HTMLElement };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const GLIDE = 480;

export function useRowMotion(
  container: React.RefObject<HTMLElement | null>,
  {
    reduced,
    resetKey,
    ranks,
    ghosts,
  }: {
    reduced: boolean;
    resetKey?: string | number;
    ranks: ReadonlyMap<string, number>;
    ghosts: React.RefObject<HTMLElement | null>;
  },
) {
  const seen = React.useRef(new Map<string, Seen>());
  const lastRanks = React.useRef(ranks);
  const lastKey = React.useRef(resetKey);
  const staggerNext = React.useRef(false);

  const read = React.useCallback(() => {
    const out = new Map<string, Seen>();
    container.current
      ?.querySelectorAll<HTMLElement>("[data-row-id]")
      .forEach((el) =>
        out.set(el.dataset.rowId!, {
          top: el.offsetTop,
          height: el.offsetHeight,
          el,
        }),
      );
    return out;
  }, [container]);

  /** The row React just removed, back on screen where it stood, leaving: sliding toward where it went, or folding. */
  const leave = (was: Seen, dy: number) => {
    const layer = ghosts.current;
    const el = was.el;
    if (!layer || el.isConnected) return;
    // No getAnimations() here (it flushes style for the whole page): the exit below is added last and replaces any
    // glide still on the element.
    el.removeAttribute("data-row-id");
    el.removeAttribute("tabindex");
    el.setAttribute("aria-hidden", "true");
    el.inert = true;
    Object.assign(el.style, {
      position: "absolute",
      left: "0",
      right: "0",
      top: `${was.top}px`,
      height: `${was.height}px`,
      margin: "0",
      overflow: "hidden",
    });
    layer.appendChild(el);
    const a = el.animate(
      dy
        ? [
            { transform: "translateY(0px)", opacity: 1, filter: "blur(0px)" },
            {
              transform: `translateY(${dy}px)`,
              opacity: 0,
              filter: "blur(3px)",
            },
          ]
        : [
            { opacity: 1, transform: "none", filter: "blur(0px)" },
            { opacity: 0, transform: "scale(0.985)", filter: "blur(4px)" },
          ],
      { duration: dy ? 360 : 280, easing: EASE, fill: "forwards" },
    );
    a.onfinish = a.oncancel = () => el.remove();
  };

  React.useLayoutEffect(() => {
    const el = container.current;
    if (!el) return;
    const before = seen.current;
    const after = read();
    const prevRanks = lastRanks.current;
    seen.current = after;
    lastRanks.current = ranks;
    const stagger = staggerNext.current;
    staggerNext.current = false;
    if (lastKey.current !== resetKey) {
      // A different page: the caller slides the whole body; nothing glides and nothing folds.
      lastKey.current = resetKey;
      return;
    }
    if (reduced || !before.size) return;

    // A typical row's height. Rows that come onto or leave the page only hint at the way they went (a row and a
    // quarter at most), so the list never shows holes while they travel.
    const heights = [...after.values()]
      .map((b) => b.height)
      .sort((a, b) => a - b);
    const rowH = heights[Math.floor(heights.length / 2)] ?? 48;
    const clamp = (dy: number) =>
      Math.max(-rowH * 1.25, Math.min(rowH * 1.25, dy));

    let order = 0;
    after.forEach((now, id) => {
      const row = now.el;
      const was = before.get(id);
      const delay = stagger ? Math.min(order++ * 16, 200) : 0;
      if (was) {
        const dy = was.top - now.top;
        if (Math.abs(dy) < 0.5) return;
        row.animate(
          [
            { transform: `translateY(${dy}px)`, zIndex: 1 },
            { transform: "translateY(0px)", zIndex: 1 },
          ],
          {
            duration: GLIDE,
            delay,
            easing: EASE,
            composite: "add",
            fill: "backwards",
          },
        );
        return;
      }
      const from = prevRanks.get(id);
      const to = ranks.get(id);
      if (from !== undefined && to !== undefined) {
        // It ranked somewhere off the page: it comes in from that side.
        row.animate(
          [
            {
              transform: `translateY(${clamp((from - to) * rowH)}px)`,
              opacity: 0,
              filter: "blur(3px)",
            },
            { transform: "translateY(0px)", opacity: 1, filter: "blur(0px)" },
          ],
          {
            duration: GLIDE,
            delay: delay / 2,
            easing: EASE,
            fill: "backwards",
          },
        );
        return;
      }
      row.animate(
        [
          { opacity: 0, filter: "blur(4px)" },
          { opacity: 1, filter: "blur(0px)" },
        ],
        { duration: 420, delay: 90, easing: EASE, fill: "backwards" },
      );
    });

    // Still in the list, just not on this page: its copy slides toward where it went. Gone for good: it folds.
    before.forEach((was, id) => {
      if (after.has(id)) return;
      const from = prevRanks.get(id);
      const to = ranks.get(id);
      leave(
        was,
        from !== undefined && to !== undefined
          ? clamp((to - from) * rowH) || rowH
          : 0,
      );
    });
  });

  // The list changed size without a render of ours (a detail opening by transition): keep the positions true.
  React.useEffect(() => {
    const el = container.current;
    if (!el) return;
    const observer = new ResizeObserver(() => {
      seen.current = read();
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, [container, read]);

  return {
    /** The next change (a sort) sets the rows off one after another. */
    stagger: () => {
      staggerNext.current = true;
    },
  };
}

